function migrateLegacyState(old){const n=defaultState();if(!old||typeof old!=='object')return n;n.day=Math.max(1,Math.min(84,Number(old.lastSelectedDay)||1));for(const [d,skills] of Object.entries(old.completed||{})){for(const s of ['reading','writing','speaking','listening'])if(skills?.[s])n.completed[`${Number(d)}:${s}`]=true;}for(const [d,r] of Object.entries(old.writingDrafts||{})){if(r?.text1)n.drafts[`writing:${d}:task1`]=r.text1;if(r?.text2)n.drafts[`writing:${d}:task2`]=r.text2;if(r?.review)n.drafts[`writing:${d}:task2:human`]=r.review;}for(const [d,r] of Object.entries(old.listeningNotes||{})){n.listening[d]={answers:{},submitted:false,steps:{},notes:[r?.review,r?.dictation].filter(Boolean).join('\n\n'),transcript:r?.transcript||'',audioName:r?.audioName||'',sourceType:'legacy-import',firstListenDone:!!r?.transcript};}for(const [d,r] of Object.entries(old.speakingNotes||{})){n.speaking[d]={transcript:r?.transcript||r?.response||'',corrected:r?.review||'',legacyImported:true};}n.errors=(old.errors||[]).map((e,i)=>({id:e.id||`legacy-${i}`,day:e.day||1,skill:e.skill||'Reading',type:e.type||'Legacy error',what:e.what||e.message||'',cause:e.cause||'Imported from the previous platform',fix:e.fix||e.prevention||'',resolved:!!e.resolved,nextReview:e.nextReview||'',at:e.at||new Date().toISOString(),legacyImported:true}));const oldCards=[...(old.vocabulary||[]),...(old.stage14?.flashcards||[])];n.savedCards=[...new Set(oldCards.map(x=>typeof x==='string'?x:(x?.word||x?.term||'')).filter(Boolean))];for(const [w,v] of Object.entries(old.stage14?.srs||{}))n.srsReviews[w]={due:v.due||v.nextReview||new Date().toISOString().slice(0,10),count:v.count||v.intervalIndex||0,last:v.last||''};const games=[...(old.intelligence?.gameHistory||[]),...(old.stage14?.gameRuns||[])];n.gameAttempts=games.map((g,i)=>({id:g.id||g.gameId||`legacy-game-${i}`,title:g.title||g.name||g.gameId||'Legacy game',day:g.day||1,score:Number(g.score||g.quality||0),correct:g.correct||0,total:g.total||0,at:g.at||g.createdAt||new Date().toISOString(),legacyImported:true}));n.mockHistory=(old.mockSessions||[]).map((m,i)=>({day:m.day||1,reading:m.readingRaw||m.reading||0,listening:m.listeningRaw||m.listening||0,writingWords:m.writingWords||0,speakingWords:m.speakingWords||0,at:m.submittedAt||m.createdAt||new Date().toISOString(),legacyImported:true}));n.legacyMigration={from:LEGACY_STORAGE,importedAt:new Date().toISOString(),completed:Object.keys(n.completed).length,drafts:Object.keys(n.drafts).length,errors:n.errors.length,games:n.gameAttempts.length};return n;}
