function cleanInstruction(value){return String(value||'').replace(/\b(?:total exactly|total)\s*(?:of\s*)?\d+\s*[-–]?\s*(?:minutes?|mins?|min(?:ute)?s?)\.?/gi,'').replace(/\b\d+(?:\s*[–-]\s*\d+)?\s*[-–]?\s*(?:minutes?|mins?|min(?:ute)?s?)\b/gi,'').replace(/\bwithin the\s+\d+\s*[-–]?\s*min(?:ute)?s?\s+block\b/gi,'').replace(/\b\d+\s*h(?:ours?)?\s*\d+\s*min(?:ute)?s?\b/gi,'').replace(/\s{2,}/g,' ').replace(/\s+([,.;:])/g,'$1').replace(/([,;])\s*([,;])/g,'$1').replace(/^[:;,\s]+|[:;,\s]+$/g,'').trim();}
