function taskEvidencePanel(skill){const r=taskRecord(skill),completed=done(skill);return `<section class="card task-evidence-card" style="margin-top:14px"><div class="between"><div><div class="eyebrow">DAILY COMPLETION & QUALITY</div><h2>Bugungi ${LABEL[skill]} topshirig‘i</h2><p class="muted small">Bu kundalik self-reflection: mehnat / jarayon sifatini 0–10 bahola. U mezonli skill natijasidan va rasmiy IELTS bandidan alohida saqlanadi.</p></div><span data-task-status="${skill}" class="pill ${completed?'good':r.checked?'info':'warn'}">${completed?'Completed & saved':r.checked?'Score + evidence needed':'Not completed'}</span></div><label class="method-step"><input type="checkbox" data-task-done="${skill}" ${r.checked?'checked':''}><span><b>Topshiriqni bajardim</b><small>Faqat natijangni saqlaganingdan keyin sessiya progressga qo‘shiladi.</small></span></label><div class="rubric-item"><label>Topshiriq sifati <output id="taskScoreOutput-${skill}">${r.scoreSet?Number(r.score).toFixed(1)+'/10':'Choose a score'}</output></label><input type="range" min="0" max="10" step="1" value="${r.scoreSet?Number(r.score):5}" data-task-score="${skill}"><small class="muted">Bu kundalik self-rating; u IELTS bandi yoki examiner bahosi emas.</small></div><div class="field"><label class="label">Dalil / qisqa reflection</label><textarea class="textarea" data-task-evidence="${skill}" placeholder="Nimani yaratding? Qaysi dalil yoki xato tahlili ballni oqlaydi? Keyingi kichik qadam nima?">${esc(r.notes||'')}</textarea></div><button class="btn teal" data-action="save-task-evidence" data-skill="${skill}">Bajarilganlik va ballni saqlash</button></section>`}
