function analyzeSpeakingTranscript(){const box=$('[data-speak-field="transcript"]'),text=String(box?.value||state.speaking[day()]?.transcript||'').trim(),words=(text.match(/\b[\w’'-]+\b/g)||[]),sentences=text.split(/[.!?]+/).map(x=>x.trim()).filter(Boolean),lower=text.toLowerCase(),fillers=(lower.match(/\b(um|uh|erm|you know|i mean)\b/g)||[]),tokens=(lower.match(/[a-z']+/g)||[]),freq={};tokens.forEach(w=>freq[w]=(freq[w]||0)+1);const repeated=Object.entries(freq).filter(([w,n])=>n>=4&&w.length>4&&!['therefore','however','because','people','which','their','these','those','about','would','could'].includes(w)).sort((a,b)=>b[1]-a[1]).slice(0,6);const flags=[];for(const [pattern,why,repair] of [[/\bi am agree\b/i,'“I am agree” is a non-standard verb pattern.','Use “I agree” or “I am in agreement”.'],[/\bpeople is\b/i,'Check subject–verb agreement in “people is”.','Use “people are” when people is the plural subject.'],[/\bhe go\b/i,'Check present-simple third-person agreement.','Use “he goes” for a present-simple third-person subject.'],[/\bmore better\b/i,'“More better” is a double comparative.','Use “better” without “more”.'],[/\bdiscuss about\b/i,'The verb “discuss” normally takes a direct object.','Use “discuss the issue”, not “discuss about the issue”.']]){const m=text.match(pattern);if(m)flags.push(`${why} Exact phrase: “${m[0]}”. ${repair}`)}const summary=[];summary.push(`Transcript length: ${words.length} words across ${sentences.length} sentence(s). This does not measure official fluency.`);summary.push(`Potential filler phrases detected: ${fillers.length}${fillers.length?` (${fillers.slice(0,8).join(', ')})`:''}. Check the audio before deciding whether they are distracting.`);if(repeated.length)summary.push('Repeated content words to review: '+repeated.map(x=>`${x[0]} ×${x[1]}`).join(', ')+'. Repetition can be appropriate; inspect the context before replacing.');else summary.push('No strong repeated-content-word pattern was detected by this simple scan.');summary.push(...flags);if(words.length<50)summary.push('This is a short sample. Record a longer answer and compare more than one response before drawing conclusions.');summary.push('Pronunciation, stress, intonation and actual hesitation cannot be judged from a text transcript; listen to the recording or ask a qualified reviewer.');const obj=state.speaking[day()]||(state.speaking[day()]={});obj.transcript=text;obj.localAudit=summary;save();const target=$('#speakingAudit');if(target)target.innerHTML=`<div class="callout info"><b>Speaking transcript coach · local text checks only</b><ul>${summary.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="muted tiny">This is not speech recognition, pronunciation scoring or an IELTS band estimate. The rules can miss valid language and may flag a phrase that is appropriate in context.</p></div>`;}
