async function importJson(file){
 if(!file)return;
 if(file.size>BACKUP_MAX_BYTES){toast('Backup 40 MB limitidan katta. Kichikroq JSON fayl tanla.');return;}
 try{
  const raw=await file.text();let payload;
  try{payload=JSON.parse(raw)}catch{throw new Error('JSON formatini o‘qib bo‘lmadi.');}
  const checked=await verifyBackupEnvelope(payload);
  if(!checked.valid)throw new Error(checked.reason||'Backup tekshiruvdan o‘tmadi.');
  const warning=checked.integrity==='sha256-verified'?'SHA-256 checksum tasdiqlandi.':'Eski backup: checksum mavjud emas; faqat tuzilma tekshirildi.';
  if(!confirm(`Import current progress?

${warning}

Current progress will be replaced. A safety snapshot will download first. Audio blobs are not included.`))return;
  await downloadBackupEnvelope(state,'pre-import-safety');
  state=mergeBackupState(defaultState(),checked.state);
  state.stage49Import={at:new Date().toISOString(),integrity:checked.integrity||'verified',sourceName:String(file.name||'backup.json').slice(0,120)};
  save();render();toast('Backup imported. Previous state safety snapshot downloaded; audio is separate.');
  const status=$('#backupStatus');if(status)status.textContent=`Import successful · ${warning}`;
 }catch(error){console.error('Backup import rejected',error);toast(`Backup import rad etildi: ${error.message||'unknown error'}`);const status=$('#backupStatus');if(status)status.textContent=`Import failed: ${error.message||'unknown error'}`;}
}
