function stage26AudioForDay(n){
  if(n>=1&&n<=23)return {...STAGE26_BC[n-1],sequence:'first-use',isReplay:false};
  if(n>=24&&n<=27)return {...STAGE26_IELTS[n-24],sequence:'official-sample',isReplay:false};
  if(n===28)return {...STAGE26_CAMBRIDGE[0],sequence:'book-test',isReplay:false};
  if(n>=29&&n<=47)return {...STAGE26_BC[23+n-29],sequence:'first-use',isReplay:false};
  if(n>=48&&n<=51)return {...STAGE26_IELTS[4+n-48],sequence:'official-sample',isReplay:false};
  if(n>=52&&n<=55)return {...STAGE26_BC[n-52],sequence:'spaced-retrieval',isReplay:true};
  if(n===56)return {...STAGE26_CAMBRIDGE[1],sequence:'book-test',isReplay:false};
  if(n>=57&&n<=69)return {...STAGE26_BC[4+n-57],sequence:'spaced-retrieval',isReplay:true};
  if(n===70)return {...STAGE26_CAMBRIDGE[2],sequence:'book-test',isReplay:false};
  if(n>=71&&n<=83)return {...STAGE26_BC[17+n-71],sequence:'spaced-retrieval',isReplay:true};
  return {...STAGE26_CAMBRIDGE[3],sequence:'book-test',isReplay:false};
}
