function stage26Field(name,label,placeholder,required=true){const f=stage26ListenData().fields;return `<div class="field"><label class="label">${label}${required?' · required':''}</label><textarea class="textarea" data-stage26-listen-field="${name}" placeholder="${esc(placeholder)}">${esc(f[name]||'')}</textarea></div>`}
function stage26Check(name,label,detail){const c=stage26ListenData().checks;return `<label class="method-step stage26-check"><input type="checkbox" data-stage26-listen-check="${name}" ${c[name]?'checked':''}><span><b>${label}</b><small>${detail}</small></span></label>`}
