const stage26RenderListeningOriginal=renderListening;
renderListening=function(){
  let html=stage26RenderListeningOriginal();
  const marker="<section class=\"card listening-hero\">";
  if(html.includes(marker))html=html.replace(marker,stage26RenderAuthenticCard()+marker);
  html=html.replace('DAILY LISTENING MISSION','OPTIONAL OFFLINE SCRIPT COMPANION');
  html=html.replace('AUDIO PLAYER','OPTIONAL SCRIPT AUDIO · SYNTHETIC FALLBACK');
  html=html.replace('In-app practice script','Original offline practice script (not authentic audio)');
  html=html.replace('84 kunlik script mavjud','Original script for offline practice');
  html=html.replace('IELTS QUESTION LAB','OPTIONAL OFFLINE SCRIPT QUESTIONS');
  html=html.replace('Save reviewed Listening result','Submit authentic Listening session');
  html=html.replace('Bu kunlik embedded savollar matn asosidagi original mashqdir. Haqiqiy IELTS formatidagi audio sinovi uchun qonuniy audio manbasini tanla.','Bu qo‘shimcha savollar faqat quyidagi original offline script uchun. Ular yuqoridagi real recording manbasining javob kaliti emas va authentic session o‘rnini bosa olmaydi.');
  return html;
};
const stage26SaveListeningOriginal=saveListeningScore;
saveListeningScore=function(){
  const ls=listeningState(),a=stage26ListenData(),f=a.fields||{},c=a.checks||{},source=stage26AudioForDay(Number(day())||1);
  const missing=[];
  if(!c.sourcePlayed)missing.push('real recordingni tinglashni tasdiqlash');
  if(!c.providerTasksDone)missing.push('manba mashqlarini bajarish');
  if(!c.transcriptReviewed)missing.push('transcript audit');
  const req={task1Result:8,gist:35,dictation:12,evidence:14,distractor:12,transfer:18,prediction:8,signpost:4};if(source.kind==='British Council lesson')req.task2Result=8;if(!f.predictionMatch)missing.push('prediction self-check');if(Number(a.challengeScore||0)<3)missing.push('Audio Evidence Hunt mini-o‘yinini tekshirish');
  for(const [k,min] of Object.entries(req)){if(String(f[k]||'').trim().length<min)missing.push(k+' dalil');}
  if(!Array.from({length:5},(_,i)=>!!ls.steps?.[`method${i}`]).every(Boolean))missing.push('Ma’rifat Jamal siklining 5 qadami');
  if(!rubricTouched('listening'))missing.push('Listening’ning 4 ta 0–10 mezoni');
  if(missing.length){toast('Authentic Listening sessiyasi hali tugamagan: '+missing.join(', ')+'.');const card=$('#stage26AuthenticListening');card?.scrollIntoView({behavior:'smooth',block:'start'});return;}
  const vals=readRubric('listening'),ev=evidenceCheck('listening','',[0,1,2,3]);if(!ev.valid){toast('Authentic Listening uchun to‘rtta mezonning har biriga aniq dalil yoz (kamida 10 belgi).');return;}const scoring=calculateEqualCriteria(vals),taskEvidence=`${source.title}. Focus: ${STAGE26_FOCUS[((Number(day())||1)-1)%14][0]}. Prediction: ${f.prediction}. Prediction check: ${f.predictionMatch}. Signpost: ${f.signpost}. Challenge: ${a.challengeScore}/3. Source task 1: ${f.task1Result}. Source task 2: ${f.task2Result||'not applicable / optional'}. Blind gist: ${f.gist}. Dictation: ${f.dictation}. Evidence: ${f.evidence}. Distractor: ${f.distractor}. Transfer: ${f.transfer}.`;
  const assessment=saveScoringRecord('listening','authentic-source',scoring,{evidence:ev.items,source:'learner_self_review',notes:`External source: ${source.title}. External provider answer key is not imported; criteria are learner self-reviewed.`});const score=scoring.score;
  a.submittedAt=new Date().toISOString();a.sourceId=source.id;a.focus=STAGE26_FOCUS[((Number(day())||1)-1)%14][0];a.score=score;
  const tr=taskRecord('listening');tr.checked=true;tr.score=score;tr.scoreSet=true;tr.notes=taskEvidence;tr.updatedAt=a.submittedAt;
  completeSkill('listening',score,{rubric:vals,assessment,sourceId:source.id,sourceTitle:source.title,sourceUrl:source.url,sourceKind:source.kind,sourceSequence:source.sequence,isSourceReplay:!!source.isReplay,authenticSession:a,taskEvidence,steps:ls.steps,notes:ls.notes,distractorAudit:ls.distractorAudit||{},distractorAuditIndex:distractorAuditScore(ls),offlineScriptPractice:ls.submitted?{rawCorrect:ls.score,rawTotal:(C().listening.questions||[]).length}:null});
  save();render();toast('Authentic Listening natijasi, ball va dalillar saqlandi.');
};
const stage26HandleClickOriginal=handleClick;
handleClick=function(e){const b=e.target.closest('[data-action]');if(b?.dataset.action==='stage26-score-challenge'){const d=stage26ListenData(),f=d.fields||{};let n=0;if(String(f.prediction||'').trim().length>=8)n++;if(String(f.signpost||'').trim().split(/\s+/).filter(Boolean).length>=2)n++;if(['Matched','Partly matched','Not matched'].includes(f.predictionMatch))n++;d.challengeScore=n;save();const v=$('#stage26ChallengeScore');if(v)v.textContent=n+'/3 micro-challenges saved';toast('Audio Evidence Hunt: '+n+'/3 amaliy checkpoint bajarildi.');return;}if(b?.dataset.action==='stage26-jump-local-audio'){const input=$('#listenAudioFile');input?.scrollIntoView({behavior:'smooth',block:'center'});input?.focus();toast('O‘zingdagi qonuniy audio faylni tanla; player shu sahifada ijro etadi.');return;}stage26HandleClickOriginal(e)};
