function writingLabFieldHandler(e){const t=e.target.closest('[data-wlab-field]');if(!t)return;const parts=t.dataset.wlabField.split(':');if(parts.length!==2)return;const [task,field]=parts,st=writingLabState();if(!st[task])st[task]={};st[task][field]=t.type==='radio'?t.value:t.value;save();}
function writingLabClickHandler(e){const b=e.target.closest('[data-wlab-action]');if(!b)return;const action=b.dataset.wlabAction,st=writingLabState();
 if(action==='check-task1'){
  const spec=R().resources?.writing?.task1||{},quiz=task1ChallengeSpec(spec),raw=document.querySelector('input[name="wlab-task1-'+day()+'"]:checked')?.value;
  st.task1=st.task1||{};const vals=(spec.values||[]).map(Number),labels=spec.labels||[];let extra=[];
  if(vals.length){const hi=labels[vals.indexOf(Math.max(...vals))],lo=labels[vals.indexOf(Math.min(...vals))];extra.push({ok:st.task1.highest===hi,label:'Highest-value selection',correct:hi});extra.push({ok:st.task1.lowest===lo,label:'Lowest-value selection',correct:lo});}
  const ok=String(raw)===String(quiz.correct),checks=extra.length?extra.filter(x=>x.ok).length:0,total=extra.length+1;st.task1.challengeAnswer=raw??'';st.task1.challengeResult={correct:ok&&checks===extra.length,score:Math.round(((ok?1:0)+checks)/total*10),explanation:quiz.explanation+(extra.length?' '+extra.map(x=>`${x.label}: ${x.ok?'correct':'correct answer is '+x.correct}`).join(' · '):'')};save();render();toast(st.task1.challengeResult.correct?'Task 1 data challenge: correct':'Task 1 challenge saved; review the explanation.');return;
 }
 if(action==='check-task2'){
  const keys=['thesis','claim1','support1','claim2','support2','conclusion'],missing=keys.filter(k=>(st.task2?.[k]||'').trim().split(/\s+/).filter(Boolean).length<(k==='thesis'?8:5));
  st.task2=st.task2||{};st.task2.planResult=missing.length?{title:'Plan hali to‘liq emas',message:'Quyidagi qismlarni rivojlantir: '+missing.join(', ')+'. Bu semantik baho emas — faqat reja maydonlari to‘ldirilganini tekshiradi.'}:{title:'Plan maydonlari to‘ldirilgan',message:'Barcha asosiy reja qismlari mavjud. Endi har bir fikr savolga javob berishini, dalilining relevantligini va paragraf ichidagi mantiqiy bog‘lanishni o‘zing tekshir.'};save();render();toast(missing.length?'Essay plan: some fields need development':'Essay plan completeness check passed');return;
 }
 if(action==='check-task2-game'){
  const answer=document.querySelector('input[name="wlab-thesis-'+day()+'"]:checked')?.value,ok=String(answer)==='0';st.task2=st.task2||{};st.task2.thesisChoice=answer??'';st.task2.gameResult={correct:ok,message:ok?'A strong thesis answers the exact question, states a position and controls the scope.':'A thesis should not merely repeat the prompt or list unrelated examples. It must answer the question and establish the argument.'};save();render();toast(ok?'Thesis challenge: correct':'Thesis challenge saved; review the principle.');return;
 }
}
