 function p35WritingReviewMarkup(){const d=p33Draft('writing'),f=d.fields||{},kind=f.taskType||'task1',need=kind==='task1'?150:250;return `<section class="p33-panel p35-review"><div class="p33-label">STAGE 35 · EVIDENCE-BASED WRITING REVIEW</div><h3>To‘liq Writing javobini to‘rtta mezon bo‘yicha tahlil qil</h3><p class="p33-small">Avval o‘zing yozgan matnni joyla. Task 1 uchun kamida 150, Task 2 uchun kamida 250 so‘z. Har bir baho aniq matn daliliga tayanishi shart.</p><label class="p33-field"><span>Qaysi ishni tekshiryapsan?</span><select class="select" data-p35-writing-kind><option value="task1" ${kind==='task1'?'selected':''}>Academic Writing Task 1 · Task Achievement</option><option value="task2" ${kind==='task2'?'selected':''}>Writing Task 2 · Task Response</option></select></label><label class="p33-field"><span>To‘liq javobing · ${need}+ so‘z</span><textarea class="textarea" data-p33-text="text" rows="9" placeholder="Paste your complete response here…">${esc(d.text||'')}</textarea><small class="p33-small">Hozirgi draft: ${p35Words(d.text)} so‘z · minimal talab: ${need}.</small></label>${p35CriterionFields('writing')}<label class="p33-field"><span>Yakuniy xulosa — eng kuchli jihat va keyingi eng muhim tuzatish</span><textarea class="textarea" data-p33-text="evidence" placeholder="Which one change would most improve this response, and why?">${esc(d.evidence||'')}</textarea></label><button class="btn primary" data-p33-submit="writing">4 mezonli dalilli self-review’ni saqlash</button>${p33LastResult('writing')}<div class="p35-note">Bu o‘quvchining o‘zini baholashi. 0–10 practice rating IELTS band score emas. IELTS’da to‘rtta mezon alohida qo‘llanadi; Task 2 umumiy Writing natijasiga Task 1’dan ko‘proq ta’sir qiladi.</div><a target="_blank" rel="noopener" href="${P35_URLS.writingCriteria}">IELTS official Writing assessment resources ↗</a></section>`;}
 function p35SpeakingReviewMarkup(){const d=p33Draft('speaking'),f=d.fields||{},clip=!!state.speaking?.[day()]?.audioName;return `<section class="p33-panel p35-review"><div class="p33-label">STAGE 35 · FOUR-CRITERION SPEAKING REVIEW</div><h3>Nutqingni qayta tingla va har bir mezonni dalil bilan tekshir</h3><p class="p33-small">Pronunciation faqat audio yozuvdan baholanadi. Transcriptdagi imlo xatolari yoki avtomatik speech recognition natijasi talaffuz sifatini ko‘rsatmaydi.</p><div class="row"><button class="btn primary" data-p33-record="start">● Record / qayta yoz</button><button class="btn outline" data-p33-record="stop">■ Stop</button><span class="p35-pill ${clip?'good':''}">${clip?'Kun uchun audio saqlangan':'Hali audio saqlanmagan'}</span></div><audio id="speechPlayer" class="p33-audio" controls></audio><label class="p33-check"><input type="checkbox" data-p33-check="p35audio" ${f.cp35audio?'checked':''}><span>Saqlangan audioni boshidan oxirigacha qayta tingladim.</span></label><label class="p33-field"><span>Uch qismdagi nutqingning birlashtirilgan transcripti · kamida 100 so‘z</span><textarea class="textarea" rows="7" data-p33-text="text" placeholder="Paste what you actually said in Parts 1, 2 and 3. Preserve repetitions and false starts before editing…">${esc(d.text||'')}</textarea><small class="p33-small">Hozirgi transcript: ${p35Words(d.text)} so‘z.</small></label>${p35CriterionFields('speaking')}<label class="p33-field"><span>Keyingi urinishda bitta ustuvor maqsad</span><textarea class="textarea" data-p33-text="evidence" placeholder="For example: shorten long pauses after questions, use clearer sentence stress, or reduce repeated fillers…">${esc(d.evidence||'')}</textarea></label><button class="btn primary" data-p33-submit="speaking">4 mezonli speaking review’ni saqlash</button>${p33LastResult('speaking')}<div class="p35-note">Bu self-review, examiner bahosi emas. IELTS Speaking’da to‘rtta mezon teng og‘irlikda ko‘riladi; avtomatik transkript pronunciation yoki rasmiy bandni bermaydi.</div><a target="_blank" rel="noopener" href="${P35_URLS.speakingDescriptors}">IELTS official Speaking band descriptors ↗</a></section>`;}
 const p35OldSkillDetail=p33SkillDetail;
 p33SkillDetail=function(id,mod){
  if(id==='writing'&&p33CurrentMode('writing')===9)return p35WritingReviewMarkup();
  if(id==='speaking'&&p33CurrentMode('speaking')===9)return p35SpeakingReviewMarkup();
  let out=p35OldSkillDetail(id,mod);
  if(id==='reading'){
   const q=C().reading.questions[p33CurrentMode(id)%C().reading.questions.length];
   if((q.options||[]).some(x=>/not given/i.test(x)))out=out.replace('</textarea></label><button class="btn primary" data-p33-submit="reading">',`</textarea></label><label class="p33-check p35-notgiven"><input type="checkbox" data-p33-check="reading_absence_basis" ${p33Draft('reading').fields?.creading_absence_basis?'checked':''}><span>Men “Not Given” javobini faqat matnda yetarli ma’lumot yo‘qligi sababli tanlayapman — tashqi bilimga tayanganim yo‘q.</span></label><button class="btn primary" data-p33-submit="reading">`);
   out=out.replace('Copy a short evidence phrase or identify the paragraph…','Matndan aynan ko‘chirilgan qisqa dalil jumlasini kiriting. NOT GIVEN uchun dalil yo‘qligini reasoning’da izohlang…');
  }
  if(id==='listening')out=out.replace('Write the phrase, number or correction cue you heard…','Audio/transcript ichidan aynan eshitilgan qisqa iborani kiriting…');
  return out;
 };
 const p35OldSubmit=p33Submit;
 p33Submit=function(id){
  const d=p33Draft(id),mode=p33CurrentMode(id),c=C(),fields=d.fields||{};
  if(id==='reading'){
   const q=c.reading.questions[mode%c.reading.questions.length],chosen=q.options?.[Number(d.answer)]||'';
   if(d.answer===undefined||String(d.answer).trim()===''){toast('Avval Reading javob variantini tanla.');return;}
   const notGiven=/not given/i.test(chosen),direct=p35ContainsQuote(c.reading.passage,d.evidence);
   if(notGiven){if(!fields.creading_absence_basis){toast('NOT GIVEN uchun matnda ma’lumot yo‘qligini tasdiqlovchi checkbox’ni belgila.');return;}if((d.reason||'').trim().length<24){toast('NOT GIVEN: nima uchun bu ma’lumot matnda yo‘qligini kamida 24 belgi bilan izohla.');return;}}
   else if(!direct){toast('Reading evidence matndan aynan olinmagan. To‘g‘ri dalil jumlasini ko‘chir yoki NOT GIVEN bo‘lsa, yo‘qligini asosla.');return;}
   if(!notGiven&&(d.reason||'').trim().length<8){toast('Daliling savolga qanday javob berishini kamida bitta aniq gap bilan tushuntir.');return;}
   const correct=p33AnswerCorrect(q,d.answer),reasonLength=(d.reason||'').trim().length;
   const score=(correct?6:2)+(notGiven?2:(direct?2:0))+(reasonLength>=40?2:1);
   p35SaveAttempt(id,d,score,correct?`Correct. ${q.explanation}`:`Review the passage and the question scope. ${q.explanation}`,correct);return;
  }
  if(id==='listening'){
   const q=c.listening.questions[p33ListenIndex(mode)];
   if(!p33Ensure().audioPlayed[day()]){toast('Avval bugungi MP3’ni oxirigacha tingla.');return;}
   if(d.answer===undefined||String(d.answer).trim()===''){toast('Avval Listening javobini kirit.');return;}
   if(!p35ContainsQuote(c.listening.script,d.evidence)){toast('Listening evidence skript ichidagi eshitilgan ibora bilan mos emas. Transcriptni audio tugagach tekshir.');return;}
   const correct=p33AnswerCorrect(q,d.answer),reasonLength=(d.reason||'').trim().length;
   const score=(correct?6:2)+2+(reasonLength>=20?2:1);
   p35SaveAttempt(id,d,score,correct?`Correct. ${q.explanation}`:`Re-listen and check the correction cue. ${q.explanation}`,correct);return;
  }
  if(id==='writing'&&mode===9){
   const kind=fields.taskType||'task1',minimum=kind==='task1'?150:250,keys=['ta','cc','lr','gra'],values=keys.map(k=>Number(fields[k]));
   if(p35Words(d.text)<minimum){toast(`${kind.toUpperCase()} javobi kamida ${minimum} so‘z bo‘lishi kerak.`);return;}
   if(keys.some((k,i)=>fields[k]===undefined||String(fields[k]).trim()===''||!Number.isFinite(values[i])||values[i]<0||values[i]>10)){toast('To‘rtta mezonning har biri uchun 0–10 practice rating kiriting.');return;}
   const missing=keys.filter(k=>String(fields[`e_${k}`]||'').trim().length<20);if(missing.length){toast('Har bir mezon uchun kamida 20 belgili matn dalili kerak: '+missing.join(', '));return;}
   if((d.evidence||'').trim().length<20){toast('Yakuniy xulosada eng muhim kuchli jihat va tuzatishni yoz.');return;}
   const avg=values.reduce((a,b)=>a+b,0)/4;
   const criterionNames=kind==='task1'?['Task Achievement','Coherence & Cohesion','Lexical Resource','Grammar']:['Task Response','Coherence & Cohesion','Lexical Resource','Grammar'];
   const notes=keys.map((k,i)=>`${criterionNames[i]}: ${fields[`e_${k}`]}`).join(' | ');
   p35SaveAttempt(id,d,avg,`${kind.toUpperCase()} self-review · ${criterionNames.map((n,i)=>`${n} ${values[i]}/10`).join('; ')}. Criterion evidence saved. Self-assessment only; no examiner band has been assigned.`);return;
  }
  if(id==='speaking'&&mode===9){
   const keys=['fc','lr','gra','pron'],values=keys.map(k=>Number(fields[k]));
   if(p35Words(d.text)<100){toast('P1/P2/P3 transcripti jami kamida 100 so‘z bo‘lsin.');return;}
   if(!state.speaking?.[day()]?.audioName){toast('Speaking baholashidan oldin haqiqiy audio yozib saqla.');return;}
   if(!fields.cp35audio){toast('Pronunciation mezoni uchun saqlangan audioni qayta tinglaganingni belgila.');return;}
   if(keys.some((k,i)=>!Number.isFinite(values[i])||values[i]<0||values[i]>10||String(fields[k]??'').trim()==='')){toast('To‘rtta Speaking mezoniga 0–10 practice rating kiriting.');return;}
   const missing=keys.filter(k=>String(fields[`e_${k}`]||'').trim().length<20);if(missing.length){toast('Har bir Speaking mezoni uchun kamida 20 belgili audio/transkript dalili kerak: '+missing.join(', '));return;}
   if((d.evidence||'').trim().length<15){toast('Keyingi urinish uchun bitta aniq maqsad yoz.');return;}
   const names=['Fluency & Coherence','Lexical Resource','Grammar Range & Accuracy','Pronunciation'];
   p35SaveAttempt(id,d,values.reduce((a,b)=>a+b,0)/4,`Speaking self-review · ${names.map((n,i)=>`${n} ${values[i]}/10`).join('; ')}. Audio replay confirmed. Transcript heuristics do not evaluate pronunciation; self-assessment only.`);return;
  }
  return p35OldSubmit(id);
 };
 function p35AcademicPanel(){const a=p35Audit,curated=Object.keys(p35State().glossary.entries).length;return `<section class="p33-panel p35-academic-panel"><div class="p33-label">STAGE 35 · ACADEMIC CONTENT & ASSESSMENT QUALITY</div><h2>Dalil, rubrika va lug‘at sifati</h2><div class="p35-metrics"><div><b>${a.readingExact}/${a.readingTotal}</b><span>Reading exact evidence</span></div><div><b>${a.readingNG}</b><span>NOT GIVEN absence cases</span></div><div><b>${a.listeningExact}/${a.listeningTotal}</b><span>Listening script evidence</span></div><div><b>${a.complete}/${a.wordCount}</b><span>Full glossary entries</span></div></div><p class="p33-small">Answer keys: Reading invalid indices ${a.readingBad}; Listening invalid indices ${a.listeningBad}. Explanations missing: Reading ${a.readingNoExplain}, Listening ${a.listeningNoExplain}. Writing Task 2 unique prompts: ${a.task2Unique}/84. Speaking prompts: ${a.speakingP1} Part 1 · ${a.speakingP2} Part 2 · ${a.speakingP3} Part 3.</p><p class="p33-small">Glossary curation on this device: ${curated} learner-reviewed entries. The 19,000-word index is not a 19,000-entry fully verified glossary.</p><div class="row"><a target="_blank" rel="noopener" href="${P35_URLS.academic}">Official IELTS sample tasks ↗</a><a target="_blank" rel="noopener" href="${P35_URLS.scoring}">Official scoring explanation ↗</a><a target="_blank" rel="noopener" href="${P35_URLS.writingDescriptors}">Writing descriptors ↗</a><a target="_blank" rel="noopener" href="${P35_URLS.speakingDescriptors}">Speaking descriptors ↗</a></div><div class="p35-note">IELTS test tasks, protected audio and complete publisher materials are not copied into this app. Local practice items are original; descriptor notes are concise paraphrases of public IELTS criteria. No automatic examiner band is claimed.</div></section>`;}
 const p35OldRenderPowerLabs=renderPowerLabs;
 renderPowerLabs=function(){let out=p35OldRenderPowerLabs();return out.replace('<section class="p33-panel p33-history">',p35AcademicPanel()+'<section class="p33-panel p33-history">');};
 function p35GlossSuggestions(query){const q=vxNormal(query);if(!q)return '<p class="p33-small">So‘z yoki ibora nomini yozib qidir.</p>';const found=WORDS.filter(w=>vxNormal(w.word).includes(q)).slice(0,8);return found.length?found.map(w=>`<button class="p35-suggestion" data-p35-gloss-select="${w.id}"><b>${esc(w.word)}</b><small>#${w.id} · ${w.meaning_en? 'existing gloss':''}${w.translation_mode==='pronunciation_index_only'?' · pronunciation-only':''}</small></button>`).join(''):'<p class="p33-small">Mos so‘z topilmadi. Yozilishini tekshir.</p>';}
 function p35GlossEditor(){const g=p35State().glossary,id=g.selectedId,w=WORDS.find(x=>String(x.id)===String(id));if(!w)return `<div class="p35-gloss-editor empty">Avval yuqoridagi qidiruv natijasidan so‘z tanla.</div>`;const n=vocabNote(w.word),draft=g.draft?.[String(w.id)]||{};const val=k=>draft[k]!==undefined?draft[k]:(n[k]||'');return `<div class="p35-gloss-editor"><div class="between"><h3>${esc(w.word)}</h3><span class="p35-pill">#${w.id} · ${esc(n.translation_mode||'legacy entry')}</span></div><p class="p33-small">Cambridge/Oxford/English Profile orqali aynan shu ma’no va usage’ni tekshir. Manbani ochish uchun tashqi havolalar:</p><div class="row"><a target="_blank" rel="noopener" href="${vxCambridgeUrl(w.word)}">Cambridge ↗</a><a target="_blank" rel="noopener" href="${vxOxfordUrl(w.word)}">Oxford ↗</a><a target="_blank" rel="noopener" href="${P35_URLS.profile}">English Profile ↗</a></div><label class="p33-field"><span>English definition · aynan tanlangan sense</span><textarea class="textarea" data-p35-gloss-field="meaning_en">${esc(val('meaning_en'))}</textarea></label><label class="p33-field"><span>O‘zbekcha tarjima / ma’no</span><textarea class="textarea" data-p35-gloss-field="uzbek">${esc(val('uzbek'))}</textarea></label><label class="p33-field"><span>Original example sentence · target so‘z tabiiy ishlatilgan</span><textarea class="textarea" data-p35-gloss-field="example">${esc(val('example'))}</textarea></label><div class="grid two"><label class="p33-field"><span>Part of speech</span><select class="select" data-p35-gloss-field="part_of_speech">${['','noun','verb','adjective','adverb','phrase','phrasal verb','idiom','preposition','conjunction','other'].map(x=>`<option value="${x}" ${val('part_of_speech')===x?'selected':''}>${x||'Select POS'}</option>`).join('')}</select></label><label class="p33-field"><span>CEFR · only after checking a sense-level source</span><select class="select" data-p35-gloss-field="cefr_level">${['Not assessed','A1','A2','B1','B2','C1','C2'].map(x=>`<option ${val('cefr_level')===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="grid two"><label class="p33-field"><span>US IPA (optional)</span><input class="input" data-p35-gloss-field="ipa_us" value="${esc(val('ipa_us'))}"></label><label class="p33-field"><span>UK IPA (optional)</span><input class="input" data-p35-gloss-field="ipa_uk" value="${esc(val('ipa_uk'))}"></label></div><label class="p33-field"><span>Sense / grammar / register / collocation note</span><textarea class="textarea" data-p35-gloss-field="sense_note">${esc(val('sense_note'))}</textarea></label><label class="p33-field"><span>Source title</span><input class="input" data-p35-gloss-field="source_title" value="${esc(val('source_title')||'') }" placeholder="e.g. Cambridge Dictionary · noun sense 2"></label><label class="p33-field"><span>Definition / translation source URL</span><input class="input" data-p35-gloss-field="source_url" value="${esc(val('source_url'))}" placeholder="https://dictionary.cambridge.org/…"></label><label class="p33-field"><span>CEFR source URL · Oxford / English Profile (only if CEFR is checked)</span><input class="input" data-p35-gloss-field="cefr_source_url" value="${esc(val('cefr_source_url'))}" placeholder="https://www.oxfordlearnersdictionaries.com/…"></label><label class="p33-check"><input type="checkbox" data-p35-gloss-verified ${draft.verifiedByUser?'checked':''}><span>Men definition, Uzbek sense, example va POS’ni yuqoridagi manba bilan tekshirdim. Bu o‘zimning local review’im, rasmiy lug‘at tasdig‘i emas.</span></label><label class="p33-check"><input type="checkbox" data-p35-cefr-verified ${draft.cefrVerified?'checked':''}><span>CEFR darajasini ham Oxford/English Profile’dagi aynan shu sense bilan tekshirdim.</span></label><div class="row"><button class="btn primary" data-p35-gloss-save="${w.id}">Local verified gloss’ni saqlash</button><button class="btn outline" data-p35-gloss-clear="${w.id}">Draftni tozalash</button></div><p class="p33-small">Saqlangan override shu qurilma/browser local state’ida turadi va JSON backup bilan ko‘chadi. Manba/verified checkbox belgilanmaguncha SRS uchun glossary-ready deb hisoblanmaydi.</p></div>`;}
 function p35GlossaryWorkbench(){const g=p35State().glossary,entries=Object.values(g.entries),verified=entries.filter(x=>x.verifiedByUser).length,cefr=entries.filter(x=>x.cefrVerified&&x.cefr_level&&x.cefr_level!=='Not assessed').length;return `<section class="card p35-glossary"><div class="between"><div><div class="eyebrow">STAGE 35 · VOCABULARY QUALITY WORKBENCH</div><h2>Glossary Curator · tekshir va boyit</h2></div><span class="pill ${verified?'good':'warn'}">${verified} local verified</span></div><p class="muted small">19,000 indeks ichida faqat to‘liq sense, tarjima, misol va POS bilan tekshirilgan birliklarni SRS’ga qo‘sh. Pronunciation-only entry’ga CEFR yoki ma’no uydirma. Har bir kiritilgan gloss shu qurilmada saqlanadi.</p><div class="p35-curation-stats"><div><b>${p35Audit.complete}</b><span>Bundled complete gloss</span></div><div><b>${verified}</b><span>My reviewed gloss</span></div><div><b>${cefr}</b><span>CEFR source checked</span></div><div><b>${p35Audit.pronOnly}</b><span>Pronunciation only</span></div></div><label class="p33-field"><span>19,000 entry ichidan so‘z qidir</span><input class="input" data-p35-gloss-search value="${esc(g.query||'')}" placeholder="e.g. alleviate, infrastructure, account for…"></label><div id="p35GlossSuggestions" class="p35-suggestions">${p35GlossSuggestions(g.query||'')}</div><div id="p35GlossEditor">${p35GlossEditor()}</div><div class="row"><button class="btn outline" data-p35-gloss-export>My curated glossary JSON ↓</button><label class="btn outline">Import curated JSON<input id="p35GlossImportFile" type="file" accept=".json,application/json" style="display:none"></label><a target="_blank" rel="noopener" href="${P35_URLS.oxford}">Oxford 3000/5000 word lists ↗</a></div><div class="p35-note">Oxford 3000/5000 lists CEFR-aligned core vocabulary; English Vocabulary Profile helps check individual meanings/senses. The app’s inherited B2/C1 labels remain estimates unless the learner records a verified sense-level source.</div></section>`;}
 const p35OldRenderVocabulary=renderVocabulary;
 renderVocabulary=function(){let out=p35OldRenderVocabulary();out=out.replace('<option value="saved">','<option value="curated">My Stage 35 reviewed glosses</option><option value="saved">');return out+p35GlossaryWorkbench();};
 const p35OldWordResults=renderWordResults;
 renderWordResults=function(q,range='all'){
  if(range!=='curated')return p35OldWordResults(q,range);
  const query=vxNormal(q),entries=Object.values(p35State().glossary.entries).map(x=>Object.assign({},WORDS.find(w=>w.id===x.id)||{},x)).filter(w=>!query||vxNormal(w.word).includes(query)||vxNormal(w.meaning_en).includes(query)||vxNormal(w.uzbek).includes(query));
  const target=$('#vocabResults');if(!target)return;const items=entries.slice(state.vocabOffset||0,(state.vocabOffset||0)+24);$('#vocabCount').textContent=`${items.length} shown · ${entries.length} my reviewed entries`;target.innerHTML=items.map(w=>`<article class="vx-word"><div class="between"><h3>${esc(w.word)}</h3><span class="vx-status good">My reviewed gloss</span></div><p><b>Definition:</b> ${esc(w.meaning_en)}</p><p><b>O‘zbekcha:</b> ${esc(w.uzbek)}</p><p><b>Example:</b> ${esc(w.example)}</p><p class="muted small">${esc(w.part_of_speech)} · CEFR ${esc(w.cefr_level||'Not assessed')} ${w.cefrVerified?'(source checked)':'(not verified)'}</p><a target="_blank" rel="noopener" href="${esc(w.source_url)}">Source ↗</a></article>`).join('')||'<div class="empty">Hali local reviewed glossary entry yo‘q.</div>';
 };
 function p35ExportGloss(){const entries=Object.values(p35State().glossary.entries),payload={app:'IELTS Boost Stage 35',exportedAt:new Date().toISOString(),note:'Learner-reviewed local glossary overrides; these are not official IELTS word lists.',entries};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`ielts-boost-stage35-glossary-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast(`${entries.length} curated glossary entries exported.`);}
 function p35SaveGloss(id){const g=p35State().glossary,w=WORDS.find(x=>String(x.id)===String(id));if(!w){toast('Word index entry not found.');return;}const d=g.draft?.[String(id)]||{},required=['meaning_en','uzbek','example','part_of_speech','source_title','source_url'];const missing=required.filter(k=>!String(d[k]||'').trim());if(missing.length){toast('Quyidagi gloss maydonlarini to‘ldir: '+missing.join(', '));return;}let url;try{url=new URL(d.source_url);if(url.protocol!=='https:')throw new Error('https required');}catch{toast('Source URL haqiqiy HTTPS havola bo‘lishi kerak.');return;}if(!d.verifiedByUser){toast('Manba bilan tekshirilganini belgilash kerak.');return;}let cefrUrl='';if(d.cefr_level&&d.cefr_level!=='Not assessed'&&d.cefrVerified){try{const cu=new URL(d.cefr_source_url);if(cu.protocol==='https:')cefrUrl=cu.href;}catch{}}const cefrOk=!!(d.cefrVerified&&cefrUrl);const cefrLevel=cefrOk?d.cefr_level:'Not assessed';const entry={id:Number(id),word:w.word,meaning_en:String(d.meaning_en).trim(),uzbek:String(d.uzbek).trim(),example:String(d.example).trim(),part_of_speech:d.part_of_speech,ipa_us:d.ipa_us||w.ipa_us||'',ipa_uk:d.ipa_uk||w.ipa_uk||'',cefr_level:cefrLevel,cefrConfidence:cefrOk?'learner_source_checked':'not_assessed',cefrVerified:cefrOk,cefr_source_url:cefrUrl,sense_note:d.sense_note||'',source_title:d.source_title,source_url:url.href,verifiedByUser:true,translation_mode:'stage35_user_reviewed',reviewedAt:new Date().toISOString()};g.entries[String(id)]=entry;state.vocabCache[w.word]=Object.assign({},state.vocabCache[w.word]||{},entry,{verifiedByUser:true});save();render();toast(`${w.word} local glossary entry saved.`);}
 function p35RenderGlossEditor(){const el=$('#p35GlossEditor');if(el)el.innerHTML=p35GlossEditor();}
