function p36Ensure(){state.stage36=state.stage36||{};const s=state.stage36;s.games=s.games||{selected:'reading',attempts:[],moduleStats:{},drafts:{},audioPlayed:{},xp:0,streak:0,lastPlayDay:0};s.games.attempts=s.games.attempts||[];s.games.moduleStats=s.games.moduleStats||{};s.games.drafts=s.games.drafts||{};s.vocabularyCache=s.vocabularyCache||{};s.speakingReports=s.speakingReports||{};s.asr=s.asr||{};return s;}
const p36Norm=x=>String(x||'').toLowerCase().normalize('NFKD').replace(/[’‘`]/g,"'").replace(/[^a-z0-9' ]/g,' ').replace(/\s+/g,' ').trim();
const p36Words=x=>(String(x||'').match(/[A-Za-z]+(?:['’-][A-Za-z]+)*/g)||[]);
