function p36GameSave(id,score,correct,total,feedback,detail={}){const g=p36Ensure().games,at=new Date().toISOString(),entry={id,day:day(),score:Math.max(0,Math.min(10,Math.round(score*10)/10)),correct,total,feedback,detail,at};g.attempts.push(entry);if(g.attempts.length>2000)g.attempts=g.attempts.slice(-2000);const m=g.moduleStats[id]||(g.moduleStats[id]={attempts:0,best:0,avg:0,mastery:0,lastScore:0});m.attempts++;m.best=Math.max(m.best,entry.score);m.avg=Math.round(((m.avg*(m.attempts-1)+entry.score)/m.attempts)*10)/10;m.lastScore=entry.score;m.mastery=Math.min(100,Math.round(m.avg*10));g.xp+=Math.round(entry.score*10);if(g.lastPlayDay!==day()){g.streak=g.lastPlayDay===day()-1?g.streak+1:1;g.lastPlayDay=day();}save();return entry;}
