function p36Question(id){const c=p36DayData();if(id==='reading')return c.reading.questions[day()%c.reading.questions.length];if(id==='listening')return c.listening.questions[([0,4,1,1,2,2,3,3,4,0][day()%10])%c.listening.questions.length];if(id==='collocations')return P36_COLLOCATIONS[(day()-1)%P36_COLLOCATIONS.length];if(id==='grammar')return P36_GRAMMAR[(day()-1)%P36_GRAMMAR.length];return null;}
function p36AnswerOptions(q,name,chosen){return (q?.options||q?.o||[]).map((x,i)=>`<label class="p36-option"><input type="radio" name="${name}" data-p36-answer value="${i}" ${String(chosen)===String(i)?'checked':''}><span>${esc(x)}</span></label>`).join('');}
function p36Progress(){const g=p36Ensure().games;const attempted=P36_MODULES.filter(m=>(g.moduleStats[m.id]?.attempts||0)>0).length;const avg= g.attempts.length?g.attempts.reduce((a,x)=>a+x.score,0)/g.attempts.length:0;const weakest=P36_MODULES.map(m=>({id:m.id,score:g.moduleStats[m.id]?.avg??null})).filter(x=>x.score!==null).sort((a,b)=>a.score-b.score)[0];return{attempted,avg:Math.round(avg*10)/10,weakest};}
