renderSpeaking=function(){let html=p36OldRenderSpeaking();const needle='<section class="speaking28-part"><div class="speaking28-parthead"><div><div class="speaking28-partbadge">PERSONAL ERROR LAB';if(html.includes(needle))return html.replace(needle,p36SpeakingPanel()+needle);return html+p36SpeakingPanel();};
let p36AsrRecognition=null,p36AsrTarget='challengeResponse',p36AsrPartial='',p36PrepInterval=null,p36InstallPrompt=null;
function p36SetAsrStatus(msg,kind='info'){const el=$('#p36AsrStatus')||$('#speechStatus');if(el){el.textContent=msg;el.className='pill '+(kind==='good'?'good':kind==='warn'?'warn':'info');}p36Ensure().asr.status=msg;}
function p36StartASR(target='challengeResponse'){const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){p36SetAsrStatus('Bu Chrome sessiyasida SpeechRecognition yo‘q. Manual transcript ishlat.', 'warn');toast('Live transcript bu browserda qo‘llanmayapti; manual transcript maydoni ishlaydi.');return false;}try{if(p36AsrRecognition){try{p36AsrRecognition.stop()}catch{}}p36AsrTarget=target;p36AsrPartial='';const s=state.speaking[day()]||(state.speaking[day()]={});p36AsrRecognition=new SR();p36AsrRecognition.lang='en-GB';p36AsrRecognition.continuous=true;p36AsrRecognition.interimResults=true;p36AsrRecognition.maxAlternatives=1;p36AsrRecognition.onresult=e=>{let finalText='',interim='';for(let i=e.resultIndex;i<e.results.length;i++){const rr=e.results[i];if(rr.isFinal)finalText+=rr[0].transcript+' ';else interim+=rr[0].transcript;}if(finalText.trim()){s[p36AsrTarget]=`${s[p36AsrTarget]||''} ${finalText.trim()}`.trim();s.transcript=p36SpeakingFullText(s);save();const el=$(`[data-speak-field="${p36AsrTarget}"]`);if(el)el.value=s[p36AsrTarget];const game=$('[data-p36-mission-transcript]');if(game)game.value=s[p36AsrTarget];}p36SetAsrStatus(`Live ASR · ${p36Words(s[p36AsrTarget]||'').length} words${interim?' · '+interim.slice(0,60):''}`,'good');};p36AsrRecognition.onerror=e=>{const code=e.error||'unknown';p36Ensure().asr.running=false;const hint=code==='not-allowed'||code==='service-not-allowed'?'Microphone permission berilmadi. Chrome site settings’dan Microphone’ga ruxsat ber yoki transcriptni qo‘lda kirit.':code==='network'?'Live speech service internetga ulanmagan. Manual transcript fallback’dan foydalan.':code==='audio-capture'?'Mikrofon qurilmasi topilmadi yoki band. Manual transcript fallback’dan foydalan.':`ASR ${code} xatosi. Manual transcript fallback’dan foydalan.`;p36SetAsrStatus(hint,'warn');try{p36AsrRecognition?.stop()}catch{}};const activeRecognition=p36AsrRecognition;p36AsrRecognition.onend=()=>{if(p36Ensure().asr.running&&p36AsrRecognition===activeRecognition){p36AsrRecognition=null;p36SetAsrStatus('ASR ulanishi yangilanmoqda…','info');setTimeout(()=>{if(p36Ensure().asr.running&&!p36AsrRecognition)p36StartASR(p36AsrTarget);},350);}};p36AsrRecognition.start();p36Ensure().asr.running=true;p36SetAsrStatus('Microphone/ASR active · gapirayotganda transcript tushadi','good');return true;}catch(e){p36SetAsrStatus('ASR ishga tushmadi: '+e.message,'warn');return false;}}
function p36StopASR(){const a=p36Ensure().asr;a.running=false;if(p36AsrRecognition){try{p36AsrRecognition.stop()}catch{}p36AsrRecognition=null;}p36SetAsrStatus('ASR stopped · transcript saved','info');}
const p36OrigStartSpeakingClip=startSpeakingClip;startSpeakingClip=async function(slot){p36AsrTarget=slot==='part1'?'part1Transcript':slot==='part2'?'part2Transcript':slot==='part3'?'part3Transcript':'challengeResponse';await p36OrigStartSpeakingClip(slot);if(speakingClipRecorder?.state==='recording'){p36StartASR(p36AsrTarget);}};
