 if(id==='speaking'){const ss=state.speaking?.[day()]||{},segKeys=['part1Transcript','part2Transcript','part3Transcript','challengeResponse'],parts=segKeys.map(k=>({key:k,text:String(ss[k]||'').trim()})).filter(x=>x.text);if(!parts.length&&String(ss.transcript||'').trim())parts.push({key:'transcript',text:String(ss.transcript).trim()});const txt=p37SpeakingFullText(ss),n=p36Words(txt).length;if(n<35){toast('Transcript hali qisqa yoki yo‘q. Record + live transcriptni boshlang yoki aytgan javobingni transcript maydoniga kiriting.');return;}const a=p36SpeakingAnalysis(txt,[]).metrics;const audio=!!(state.speaking?.[day()]?.challengeClipName||state.speaking?.[day()]?.part1ClipName||state.speaking?.[day()]?.part2ClipName||state.speaking?.[day()]?.part3ClipName||state.speaking?.[day()]?.audioName);const completeness=Math.min(3,parts.length);const length=Math.min(2,Math.floor(n/60));const structure=Math.min(2,a.sentences>=4?2:a.sentences>=2?1:0);const evidence=reason.length>=10||String(state.speaking?.[day()]?.pronunciationNotes||'').length>=10?1:0;score=Math.min(10,2+completeness+length+structure+evidence+(audio?1:0));feedback=`${n} words across ${parts.length} transcript segment(s); ${a.sentences} sentence units; ${a.lexicalDiversity}% unique-token ratio; ${a.fillers} possible fillers. ${audio?'Audio clip saved.':'No saved audio found; text-only sample.'} Pronunciation needs an audio replay.`;next='Review the segment-level transcript report, select one grammar/lexical repair, then re-record and compare.';state.speaking[day()].stage37LastTranscript=txt;}
