 if(id==='pronunciation'){const checked=Object.values(draft.checks||{}).filter(Boolean).length;if(checked<4||reason.length<15){toast('Kamida 4 ta self-review checkpoint va timestamp bilan 15+ belgili audio dalili kerak.');return;}score=Math.min(10,3+checked+Math.min(2,Math.floor(reason.length/60)));feedback=`${checked}/6 pronunciation checkpoints reviewed. Self-review only; no automatic accent judgement.`;next='Repeat the same phrase once more, focusing on the one timestamp you recorded.';}
 if(id==='paraphrase'){const n=p36Words(draft.text).length,r=p36Words(draft.reason).length,checked=!!draft.checks?.meaning;if(n<20||r<10||!checked){toast('20+ so‘zli paraphrase, 10+ so‘zli izoh va meaning-check belgisi kerak.');return;}const source=(d.reading.passage.split(/(?<=[.!?])\s+/).find(x=>x.trim().length>65)||'');const a=new Set(p36Words(source).map(x=>x.toLowerCase())),b=new Set(p36Words(draft.text).map(x=>x.toLowerCase())),overlap=[...a].filter(x=>b.has(x)&&x.length>4).length,changed=Math.max(0,a.size-overlap);score=Math.min(10,4+(changed>=3?2:1)+(r>=20?2:1)+(n>=35?1:0));feedback=`${n} words; ${changed} source content terms not reused. This is a lexical-difference signal, not semantic equivalence proof. Compare scope, certainty and claim manually.`;next='Ask whether the subject, claim, certainty and comparison are unchanged; then paraphrase another sentence.';}
 if(id==='grammar'){if(draft.answer==null||draft.answer===''){toast('Grammar variantini tanla.');return;}const correct=Number(draft.answer)===Number(q.a),r=p36Words(draft.reason).length,n=p36Words(draft.text).length;if(r<7||n<8){toast('Rule explanation 7+ words and transfer sentence 8+ words.');return;}score=(correct?6:2)+(r>=14?2:1)+(n>=14?2:1);feedback=`${correct?'Correct rule retrieval.':'Review the rule and answer key.'} New transfer sentence saved.`;next='Use the same grammatical structure in a new subject/topic tomorrow.';}
 if(id==='vocabulary'){const word=WORDS.find(w=>w.id===Number(draft.wordId));if(!word)return;const n=p36Words(draft.definition).length,t=p36Words(draft.translation).length,s=p36Words(draft.text).length;if(n<4||t<1||s<8||!draft.rating){toast('Definition, Uzbek meaning, 8+ word sentence and SRS rating all required.');return;}const answer=(word.meaning_en+' '+word.uzbek).toLowerCase(),attempt=(draft.definition+' '+draft.translation).toLowerCase(),hits=p36Words(answer).filter(x=>x.length>3&&attempt.includes(x)).length;score=Math.min(10,3+(hits>=3?3:hits>=1?2:0)+(s>=14?2:1)+(draft.rating==='good'||draft.rating==='easy'?2:1));const v=p37Ensure().vocabulary,srs=v.srs[word.word]||{interval:0,reps:0};const days={again:1,hard:2,good:4,easy:8};srs.interval=days[draft.rating];srs.reps=(srs.reps||0)+1;srs.due=new Date(Date.now()+srs.interval*86400000).toISOString().slice(0,10);srs.last=day();v.srs[word.word]=srs;feedback=`Recall match signal ${hits}; sentence ${s} words. SRS next review: ${srs.due}. Meaning matching is approximate; check exact sense.`;next='Retrieve the word again on the due date and use it in a new sentence.';}
 if(id==='fluency'){const f=draft.fields||{},keys=['claim','reason','example','qualification'],lengths=keys.map(k=>p36Words(f[k]).length),done=lengths.filter(n=>n>=5).length,total=lengths.reduce((a,b)=>a+b,0);if(done<4){toast('Claim, reason, example va qualification — to‘rttalasini ham 5+ so‘z bilan to‘ldir.');return;}score=Math.min(10,4+Math.min(2,Math.floor(total/30))+(lengths.every(n=>n>=8)?2:1)+(total>=55?1:0));feedback=`All 4 discourse functions completed (${total} words in the plan). This is structure practice, not a fluency band.`;next='Connect the four points in one spoken response without reading the labels.';}
