function p37Next(id){const m=p37ModuleState(id);if(!(m.doneByDay?.[day()]||[]).includes(m.round)){toast('Avval round natijasini saqla.');return;}if(m.round>=2){toast('3 round tugadi. Restart 3-round run orqali yangi session boshlashing mumkin.');return;}m.round++;save();render();}
function p37Reset(id){const m=p37ModuleState(id);m.round=0;m.doneByDay=m.doneByDay||{};m.doneByDay[day()]=[];m.done=m.doneByDay[day()];save();render();}
function p37HubSelect(id){p37G().selected=id;save();render();}
