function p37SpeakingReport(){const s=state.speaking[day()]||(state.speaking[day()]={}),partSegments=[['Part 1','part1Transcript'],['Part 2 long turn','part2Transcript'],['Part 3 discussion','part3Transcript'],['Daily challenge','challengeResponse']].map(([label,key])=>({label,key,text:String(s[key]||'').trim()})).filter(x=>x.text),segments=partSegments.length?partSegments:(String(s.transcript||'').trim()?[{label:'Combined transcript',key:'transcript',text:String(s.transcript||'').trim()}]:[]);const full=p37SpeakingFullText(s);if(p36Words(full).length<15){toast('Transcript topilmadi yoki 15 so‘zdan kam. Avval microfon/live transcript yoki manual dictation ishlat.');return null;}const a=p37AnalyzeSpeaking(full),partReports=segments.map(x=>({label:x.label,text:x.text,...p37AnalyzeSpeaking(x.text)}));const confidences=Object.values(s.asrMeta||{}).flatMap(x=>x.confidences||[]).filter(Number.isFinite),meanConfidence=confidences.length?Math.round(confidences.reduce((a,b)=>a+b,0)/confidences.length*100):null;const rubric=s.stage36Rubric||{},keys=['fc','lr','gra','pron'],complete=keys.every(k=>rubric[k]&&Number.isFinite(Number(rubric[k].score))&&String(rubric[k].evidence||'').trim().length>=10),average=complete?Math.round(keys.reduce((sum,k)=>sum+Number(rubric[k].score),0)/4*10)/10:null;const report={day:day(),at:new Date().toISOString(),wordCount:a.metrics.words,metrics:a.metrics,hints:a.hints,segments:partReports,meanAsrConfidence:meanConfidence,rubric, rubricComplete:complete,rubricAverage:average,source:'IELTS Boost Stage 38 deterministic transcript heuristics; learner evidence review; not an examiner score'};p37Ensure().speakingReports[day()]=report;s.stage37Report=report;s.transcript=full;save();return report;}
