// Vocabulary: 10K active index, 4K pronunciation + translation lookup cohort, 9K definition lookup eligibility. Definitions/translations cache after online retrieval.
function p37VocabularyPanel(){return `<section class="card p37-vocab-panel"><div class="eyebrow">STAGE 40 · 19,000-WORD VOCABULARY ENGINE</div><h2>19K vocabulary index · pronunciation, meaning and active recall</h2><p class="p37-note">All 19,000 indexed terms are searchable. The first 4,000 have US/UK IPA fields for the pronunciation + Uzbek translation lookup cohort. The first 9,000 are eligible for online English-definition lookup and local caching. Only 671 entries currently ship with a complete offline English definition, Uzbek gloss, example and part of speech; the rest are fetched on demand, not falsely presented as preloaded.</p><div class="p37-vocab-stats"><div><b>19,000</b><small>searchable indexed words</small></div><div><b>4,000</b><small>IPA + Uzbek lookup cohort</small></div><div><b>671</b><small>bundled complete offline glosses</small></div><div><b>9,000</b><small>definition lookup target</small></div></div><div class="p37-vocab-search"><input class="input" id="p37VocabSearch" placeholder="Search e.g. substantial, mitigate, infrastructure" autocomplete="off"><select class="select" id="p37VocabFilter"><option value="all">All 19,000 indexed words</option><option value="ipa">4,000 pronunciation + translation cohort</option><option value="offline">Bundled offline glosses</option><option value="lookup">Needs online lookup</option><option value="due">SRS review due</option></select></div><div id="p37VocabResults" class="p37-vocab-results"><p class="muted">At least 2 letters to search.</p></div><div id="p37VocabDetail" class="p37-vocab-detail"><p>Select a word to open its IPA, definition, translation, example and spaced-repetition controls.</p></div><div class="p37-note">Dictionary sources: Free Dictionary API for English definitions and phonetics; MyMemory for provisional English→Uzbek machine translation. Translation may be sense-ambiguous; check Cambridge/Oxford before memorising. No copyrighted dictionary definitions or IELTS book content are redistributed.</div></section>`;}
renderVocabulary=function(){return p36OrigRenderVocabulary()+p37VocabularyPanel();};
function p37VocabResults(query,filter='all'){const box=$('#p37VocabResults');if(!box)return;const q=p36Norm(query);if(filter==='due'){const due=Object.entries(p37Ensure().vocabulary.srs).filter(([,v])=>v.due<=new Date().toISOString().slice(0,10)).map(([w])=>w);const words=WORDS.slice(0,19000).filter(w=>due.includes(w.word)).slice(0,30);box.innerHTML=words.length?words.map(w=>`<button class="p37-vocab-hit" data-p37-word="${w.id}"><b>${esc(w.word)}</b><small>Review due · US ${esc(w.ipa_us||'—')}</small></button>`).join(''):'<p>No SRS reviews due today.</p>';return;}if(q.length<2){box.innerHTML='<p class="muted">Enter at least 2 letters.</p>';return;}let matches=WORDS.slice(0,19000).filter(w=>p36Norm(w.word).includes(q));const cached=w=>({...w,...(p36Ensure().vocabularyCache[w.word]||{}),...(p37Ensure().vocabulary.cache[w.word]||{})});if(filter==='ipa')matches=matches.filter(w=>w.id<=4000&&w.ipa_us&&w.ipa_uk);if(filter==='offline')matches=matches.filter(w=>{const x=cached(w);return x.meaning_en&&x.uzbek&&x.example;});if(filter==='lookup')matches=matches.filter(w=>{const x=cached(w);return !(x.meaning_en&&x.uzbek);});box.innerHTML=matches.length?matches.slice(0,24).map(w=>{const x=cached(w);return `<button class="p37-vocab-hit" data-p37-word="${w.id}"><b>${esc(w.word)}</b><small>US ${esc(w.ipa_us||'—')} · ${x.meaning_en&&x.uzbek?'cached gloss':'online lookup'}</small></button>`;}).join(''):'<p>No matching entries. Check the spelling or use the online dictionary lookup.</p>';}
function p37VocabDetail(id){const w=WORDS.find(x=>x.id===Number(id));if(!w)return;const c={...(p36Ensure().vocabularyCache[w.word]||{}),...(p37Ensure().vocabulary.cache[w.word]||{})},base={...(w||{}),...(vocabNote(w.word)||{}),...c},v=p37Ensure().vocabulary,srs=v.srs[w.word];const box=$('#p37VocabDetail');box.innerHTML=`<h3>${esc(w.word)}</h3><p class="p37-ipa">US ${esc(w.ipa_us||c.ipa_api||'—')} · UK ${esc(w.ipa_uk||'—')}</p><div class="p37-row"><button class="btn small outline" data-p36-say="${esc(w.word)}">🔊 Say word</button><a target="_blank" rel="noopener" href="${vxCambridgeUrl(w.word)}">Cambridge ↗</a><a target="_blank" rel="noopener" href="${vxOxfordUrl(w.word)}">Oxford ↗</a></div><div class="p37-vocab-sense"><b>English definition</b><p>${esc(base.meaning_en||c.meaning_en||'Not loaded yet')}</p><b>O‘zbekcha ma’no</b><p>${esc(base.uzbek||c.uzbek||'Not loaded yet')}</p><b>Example</b><p>${esc(base.example||c.example||'Not loaded yet')}</p><small>POS: ${esc(base.part_of_speech||c.part_of_speech||w.part_of_speech||'not assessed')} · source: ${esc(c.source||base.source||w.source||'not recorded')}</small></div><div class="p37-row"><button class="btn primary small" data-p37-lookup="${w.id}">Fetch definition + Uzbek translation</button><button class="btn outline small" data-p37-lookup-def="${w.id}">Definition only</button><button class="btn outline small" data-p37-lookup-uz="${w.id}">Uzbek translation only</button></div><div class="p37-row"><button class="btn outline small" data-p37-srs="${w.id}" data-rating="again">Again</button><button class="btn outline small" data-p37-srs="${w.id}" data-rating="hard">Hard</button><button class="btn outline small" data-p37-srs="${w.id}" data-rating="good">Good</button><button class="btn outline small" data-p37-srs="${w.id}" data-rating="easy">Easy</button></div><p class="p37-note">${srs?`SRS: ${srs.reps} reviews · next due ${srs.due}`:'SRS not yet scheduled.'} Translations fetched from machine translation must be checked for the intended sense. IPA may be machine-generated.</p>`;}
async function p37LookupBoth(id){const w=WORDS.find(x=>x.id===Number(id));if(!w)return;const box=$('#p37VocabDetail');if(box)box.insertAdjacentHTML('beforeend','<p class="p37-status">Fetching dictionary and Uzbek meaning…</p>');const results=await Promise.allSettled([p36LookupDefinition(w.word),p36LookupUzbek(w.word)]);const ok=results.filter(x=>x.status==='fulfilled').length;p37VocabDetail(w.id);toast(`${ok}/2 lookup requests completed. Review exact sense.`);}
function p37ScheduleSrs(id,rating){const w=WORDS.find(x=>x.id===Number(id));if(!w)return;const days={again:1,hard:2,good:4,easy:8},s=p37Ensure().vocabulary.srs;s[w.word]=s[w.word]||{reps:0};s[w.word].reps++;s[w.word].interval=days[rating];s[w.word].last=new Date().toISOString();s[w.word].due=new Date(Date.now()+days[rating]*86400000).toISOString().slice(0,10);save();p37VocabDetail(w.id);toast(`Next review: ${s[w.word].due}`);}
document.addEventListener('click',e=>{const t=e.target.closest('[data-p37-word],[data-p37-lookup],[data-p37-lookup-def],[data-p37-lookup-uz],[data-p37-srs]');if(!t)return;if(t.dataset.p37Word){p37VocabDetail(t.dataset.p37Word);return;}if(t.dataset.p37Lookup){p37LookupBoth(t.dataset.p37Lookup);return;}if(t.dataset.p37LookupDef){const w=WORDS.find(x=>x.id===Number(t.dataset.p37LookupDef));if(w)p36LookupDefinition(w.word).then(()=>{p37VocabDetail(w.id);toast('Definition saved to local cache.');}).catch(x=>toast(x.message));return;}if(t.dataset.p37LookupUz){const w=WORDS.find(x=>x.id===Number(t.dataset.p37LookupUz));if(w)p36LookupUzbek(w.word).then(()=>{p37VocabDetail(w.id);toast('Translation cached. Verify the sense.');}).catch(x=>toast(x.message));return;}if(t.dataset.p37Srs){p37ScheduleSrs(t.dataset.p37Srs,t.dataset.rating);return;}},true);
document.addEventListener('input',e=>{if(e.target.matches('#p37VocabSearch'))p37VocabResults(e.target.value,$('#p37VocabFilter')?.value||'all');},true);document.addEventListener('change',e=>{if(e.target.matches('#p37VocabFilter'))p37VocabResults($('#p37VocabSearch')?.value||'',e.target.value);if(e.target.matches('[data-p37-field="rating"]'))p37Draft('vocabulary').rating=e.target.value;},true);
