const P39_VERSION='39.0.0';
window.__IELTS_BOOST_STAGE39__={version:P39_VERSION,focus:['speaking-transcript','advanced-games','vocabulary','pwa-install']};

// Show a voice-to-text control directly beside the real IELTS raw transcript textarea.
const p39SpeechFields=[
 ['part1Transcript','PART 1 · LIVE VOICE-TO-TEXT','Answer the three short questions. The recognized words appear in the field directly below.'],
 ['part2Transcript','PART 2 · LIVE VOICE-TO-TEXT','Start the recognition, speak for 1–2 minutes, then stop. The transcript remains in the Part 2 field.'],
 ['part3Transcript','PART 3 · LIVE VOICE-TO-TEXT','Speak in extended turns. Your transcript is stored separately from Parts 1 and 2.'],
 ['challengeResponse','DAILY CHALLENGE · LIVE VOICE-TO-TEXT','This challenge has its own transcript and will not overwrite formal Part 2.']
];
function p39VoiceBar(key,title,help){return `<div class="p39-voice-box"><div class="p39-voice-title"><b>🎙 ${title}</b><span data-p39-asr-status="${key}" aria-live="polite">Ready · press Start</span></div><p>${help}</p><div class="p39-voice-actions"><button type="button" class="btn primary small" data-p37-asr-start="${key}">Start live transcript</button><button type="button" class="btn outline small" data-p37-asr-stop>Stop</button><button type="button" class="btn outline small" data-p39-focus="${key}">Open text field</button><button type="button" class="btn outline small" data-p37-clear-transcript="${key}">Clear</button></div><label class="p39-language">Recognition language <select data-p39-lang="${key}" class="select"><option value="en-GB" selected>English (UK)</option><option value="en-US">English (US)</option></select></label><p class="p39-fallback">Live recognition needs browser support, microphone permission and usually internet. If it is unavailable, tap the transcript field and use the Samsung Keyboard/Gboard microphone (English voice typing).</p></div>`;}
const p39OldRenderSpeaking=renderSpeaking;
renderSpeaking=function(){
 let h=p39OldRenderSpeaking();
 for(const [key,title,help] of p39SpeechFields){
  const re=new RegExp('(<textarea[^>]*data-speak-field="'+key+'"[^>]*>)');
  if(re.test(h))h=h.replace(re,p39VoiceBar(key,title,help)+'$1');
 }
 return h;
};

// The same status is mirrored beside the relevant field and in the transcript coach panel.
const p39OldSetASRStatus=p37SetASRStatus;
p37SetASRStatus=function(msg,kind='info',target=p37RecognitionTarget){
 try{p39OldSetASRStatus(msg,kind,target);}catch(_){}
 document.querySelectorAll(`[data-p39-asr-status="${target}"]`).forEach(el=>{el.textContent=msg;el.className='p37-status '+kind;});
 document.querySelectorAll(`[data-p37-status-target="${target}"]`).forEach(el=>{el.textContent=msg;el.className='p37-status '+kind;});
};
// Language choice belongs to the currently selected segment. The recognizer uses it at every restart.
window.__IELTS_BOOST_SPEECH_LANG__='en-GB';
document.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-p39-lang]')){window.__IELTS_BOOST_SPEECH_LANG__=t.value||'en-GB';p37SetASRStatus('Recognition language: '+window.__IELTS_BOOST_SPEECH_LANG__,'info',t.dataset.p39Lang);}},true);
document.addEventListener('click',e=>{const t=e.target.closest('[data-p39-focus]');if(!t)return;const field=document.querySelector(`[data-speak-field="${t.dataset.p39Focus}"]`);if(field){field.scrollIntoView({behavior:'smooth',block:'center'});field.focus();}},true);
// Recognition language is selected by the visible field-level selector.
// Replace old panel statuses with data selectors so they update alongside field-level statuses.
document.querySelectorAll('[id^="p37Status-"]').forEach(el=>{const key=el.id.replace('p37Status-','');el.dataset.p37StatusTarget=key;});

// Advanced mission arcade: add unlock/achievement feedback without resetting existing XP or attempts.
function p39AchievementState(){const g=p37G(),mods=P37_MODULES.map(x=>p37ModuleState(x.id)),tried=mods.filter(x=>x.attempts>0).length,perfect=g.attempts.filter(x=>x.score>=9).length,rounds=mods.reduce((n,x)=>n+(x.doneByDay?.[day()]||[]).length,0);return[
 {name:'First Mission',desc:'Complete the first game round',ok:g.attempts.length>=1,icon:'🏁'},
 {name:'Four-Skill Explorer',desc:'Try all four IELTS core skills',ok:['reading','listening','writing','speaking'].every(id=>(g.modules[id]?.attempts||0)>0),icon:'🎯'},
 {name:'Ten-Lab Explorer',desc:'Try each of the ten game labs',ok:tried===10,icon:'🧭'},
 {name:'Precision Streak',desc:'Earn three results of 9/10 or higher',ok:perfect>=3,icon:'⭐'},
 {name:'Daily 10',desc:'Complete ten rounds today',ok:rounds>=10,icon:'🔥'}
 ];}
const p39OldGameHub=p37GameHub;
p37GameHub=function(){
 let h=p39OldGameHub();const g=p37G(),pr=p37GameProgress(),xp=g.xp||0,progress=xp%500,ach=p39AchievementState();
 const achievements=`<section class="p39-achievements"><div class="p39-ach-head"><div><div class="eyebrow">MASTERY TRACK</div><h3>XP level & achievements</h3></div><b>LEVEL ${pr.level}</b></div><div class="p39-xp-track"><span style="width:${Math.round(progress/5)}%"></span></div><p>${progress}/500 XP to the next level · ${g.attempts.length} submitted rounds · ${ach.filter(x=>x.ok).length}/${ach.length} achievements unlocked</p><div class="p39-ach-grid">${ach.map(a=>`<article class="${a.ok?'unlocked':''}"><b>${a.icon} ${esc(a.name)}</b><small>${esc(a.desc)}</small><span>${a.ok?'UNLOCKED':'LOCKED'}</span></article>`).join('')}</div></section>`;
 return h.replace('<div class="p37-module-grid">',achievements+'<div class="p37-module-grid">');
};

