const P39_OFFLINE_GLOSS_COUNT=(()=>{try{return WORDS.filter(w=>w.meaning_en&&w.uzbek&&w.example&&w.part_of_speech).length;}catch(_){return 0;}})();
const p39OldVocabularyPanel=p37VocabularyPanel;
p37VocabularyPanel=function(){return p39OldVocabularyPanel().replaceAll('671',String(P39_OFFLINE_GLOSS_COUNT)).replace('STAGE 38','STAGE 40').replace('Only '+P39_OFFLINE_GLOSS_COUNT+' entries currently ship','Only '+P39_OFFLINE_GLOSS_COUNT+' entries currently ship');};
const p39OldVocabDetail=p37VocabDetail;
p37VocabDetail=function(id){p39OldVocabDetail(id);const box=$('#p37VocabDetail');if(!box)return;const w=WORDS.find(x=>x.id===Number(id));if(!w)return;const s=p37Ensure().vocabulary.cache[w.word]||{};const cohort=Number(w.id)<=4000;const label=cohort?'IPA + translation cohort':'Definition lookup';const n=document.createElement('p');n.className='p39-vocab-source';n.textContent=`${label} · US/UK IPA: ${w.ipa_us||'not available'} / ${w.ipa_uk||'not available'}. Dictionary entry status: ${s.meaning_en&&s.uzbek?'cached bilingual gloss':w.meaning_en&&w.uzbek?'bundled glossary':'lookup not yet cached'}.`;box.appendChild(n);};

// PWA diagnostics use the page directory as the project-app scope, validate every icon and report why a native prompt may be absent.
async function p39CheckPwa(){
 const box=$('#p37PwaDiagnostics');if(!box)return;
 const rows=[];const add=(name,ok,detail)=>rows.push(`<div class="p37-pwa-row"><b>${ok?'✓':'!'} ${esc(name)}</b><span class="${ok?'good':'warn'}">${esc(detail)}</span></div>`);
 add('Secure HTTPS',location.protocol==='https:'&&window.isSecureContext,location.protocol+' · '+location.origin);
 const link=document.querySelector('link[rel="manifest"]');let manifest=null,manifestOk=false;
 try{const r=link?await fetch(link.href,{cache:'no-store'}):null;if(r?.ok){manifest=await r.json();manifestOk=true;}}catch(err){}
 add('Manifest fetched',manifestOk,link?link.href:'manifest link missing');
 let scopePath='',startPath='';
 if(manifest&&link){try{scopePath=new URL(manifest.scope||'./',link.href).pathname;startPath=new URL(manifest.start_url||'./',link.href).pathname;}catch(_){}}
 const pagePath=location.pathname,scopeOk=!!scopePath&&pagePath.startsWith(scopePath)&&startPath.startsWith(scopePath);
 add('GitHub project scope',scopeOk,`page ${pagePath} · scope ${scopePath||'missing'} · start ${startPath||'missing'}`);
 const iconRows=[];
 for(const icon of manifest?.icons||[]){try{const u=new URL(icon.src,link.href),r=await fetch(u.href,{cache:'no-store'});const bmp=await createImageBitmap(await r.blob());const d=String(icon.sizes||'').split('x').map(Number),ok=r.ok&&d.length===2&&bmp.width===d[0]&&bmp.height===d[1];add(`Icon ${icon.sizes}`,ok,`${bmp.width}×${bmp.height} · ${u.pathname}`);iconRows.push(ok);bmp.close();}catch(e){add(`Icon ${icon.sizes||'unknown'}`,false,'missing, blocked or invalid image');iconRows.push(false);}}
 const hasRequiredIcons=(manifest?.icons||[]).some(x=>x.sizes==='192x192'&&x.purpose==='any')&&(manifest?.icons||[]).some(x=>x.sizes==='512x512'&&x.purpose==='any');
 add('Install icon requirements',hasRequiredIcons&&iconRows.every(Boolean),`${(manifest?.icons||[]).length} declared icons`);
 const displayOk=manifest?.display==='standalone'||(manifest?.display_override||[]).includes('standalone');add('Standalone display mode',displayOk,manifest?.display||'not declared');
 let reg=null;try{reg=await navigator.serviceWorker?.getRegistration(new URL('./',location.href).pathname);}catch(_){}
 const swOk=!!reg&&!!reg.active;add('Service worker active',swOk,reg?.scope||'not registered yet');
 const controlled=!!navigator.serviceWorker?.controller;add('Page controlled by service worker',controlled,controlled?'controlled':'Reload the HTTPS page once after installation');
 let swFetch=false;try{const r=await fetch(new URL('./sw.js',location.href),{cache:'no-store'});swFetch=r.ok;}catch(_){}add('Service worker file reachable',swFetch,new URL('./sw.js',location.href).pathname);
 const installed=matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;add('Standalone app mode',installed,installed?'running as installed app':'currently a browser tab');
 const prompt=!!(p36InstallPrompt||p37InstallPrompt);add('Chrome install event',prompt,prompt?'native install prompt captured':'not offered by the browser; see platform conditions below');
 const likelyEligible=manifestOk&&scopeOk&&hasRequiredIcons&&iconRows.every(Boolean)&&displayOk&&swOk;
 const diagnosis=likelyEligible?(prompt?'PWA criteria look good; use the Install app button.':'Manifest, icons and SW pass. Android Chrome may still choose shortcut depending on WebAPK/GMS support, engagement or its installability evaluator.'):'Fix every failed manifest/icon/SW row first; Chrome cannot create a native app icon while a required criterion is failing.';
 box.innerHTML=rows.join('')+`<div class="p39-diagnosis"><b>Diagnosis</b><p>${esc(diagnosis)}</p><p>URL: ${esc(location.href)}</p></div>`;
 return{manifestOk,scopeOk,hasRequiredIcons,swOk,controlled,installed,prompt,likelyEligible};
}
p37CheckPwa=p39CheckPwa;
