const P40_VERSION='40.0.0';

// 24 contextual collocation questions and 24 grammar transfer questions, authored for IELTS Boost.
const P40_COLLOCATIONS=[
 {q:'The new policy is expected to ___ a significant impact on public transport.',options:['make','have','do','give'],a:1,focus:'have an impact on + noun',explanation:'Have an impact on is the natural verb–noun collocation. “Make an impact” is possible in other contexts, but the structure “have a … impact on” is fixed here.'},
 {q:'Researchers must ___ a distinction between correlation and causation.',options:['draw','take','do','create'],a:0,focus:'draw a distinction between A and B',explanation:'Draw a distinction is a standard academic collocation meaning to identify a difference.'},
 {q:'The government should ___ priority to long-term educational investment.',options:['give','put','make','take'],a:0,focus:'give priority to',explanation:'Give priority to is the fixed verb–noun collocation in this sentence; put priority on would require the preposition “on”.'},
 {q:'The committee will ___ a decision after reviewing the evidence.',options:['make','do','perform','build'],a:0,focus:'make a decision',explanation:'Make a decision is the established collocation; “do a decision” is not idiomatic.'},
 {q:'The report provides ___ evidence that the intervention was effective.',options:['strongly','strong','strength','strengthen'],a:1,focus:'strong evidence',explanation:'Strong is the adjective that naturally modifies evidence.'},
 {q:'A lack of funding can ___ progress in rural schools.',options:['hinder','prevent to','avoid','refuse'],a:0,focus:'hinder progress',explanation:'Hinder progress means make progress more difficult. It takes a direct object.'},
 {q:'The findings are broadly ___ with earlier research.',options:['consistent','consistency','consistently','consisting'],a:0,focus:'consistent with',explanation:'Consistent with is the adjective + preposition pattern.'},
 {q:'Students need to ___ responsibility for their own learning.',options:['take','do','make','carry'],a:0,focus:'take responsibility for',explanation:'Take responsibility for is the standard verb–noun pattern.'},
 {q:'The city aims to ___ pressure on its overcrowded roads.',options:['reduce','lower down','decrease off','shorten'],a:0,focus:'reduce pressure on',explanation:'Reduce pressure on is idiomatic and precise.'},
 {q:'The study raises ___ concerns about data privacy.',options:['seriously','serious','seriousness','serioused'],a:1,focus:'serious concerns',explanation:'Serious is the adjective that modifies concerns.'},
 {q:'The proposal could ___ access to healthcare in remote areas.',options:['improve','increase up','rise','grow up'],a:0,focus:'improve access to',explanation:'Improve access to is the correct collocation; “increase access” can also be grammatical, but the best one-word fit among options is improve.'},
 {q:'It is difficult to ___ a balance between quality and cost.',options:['strike','hit on','do','make'],a:0,focus:'strike a balance between',explanation:'Strike a balance is a natural fixed phrase in formal English.'},
 {q:'The company must ___ strict standards for data protection.',options:['meet','do','reach to','make'],a:0,focus:'meet standards',explanation:'Meet standards means satisfy the required level.'},
 {q:'The project aims to ___ awareness of environmental issues.',options:['raise','rise','grow up','lift up'],a:0,focus:'raise awareness of',explanation:'Raise awareness of is the standard transitive phrase.'},
 {q:'The results should be interpreted with ___.',options:['caution','careful','carefully','cautiousness'],a:0,focus:'interpret something with caution',explanation:'Caution is a noun and completes the fixed phrase “with caution”. “Careful” is an adjective and cannot stand alone in this slot.'},
 {q:'A reliable public transport system can ___ traffic congestion.',options:['alleviate','relieve from','solve up','reduce down'],a:0,focus:'alleviate congestion',explanation:'Alleviate congestion is formal and natural; reduce congestion is also possible but not offered.'},
 {q:'The university offers students the opportunity to ___ practical experience.',options:['gain','win','earn out','take up'],a:0,focus:'gain experience',explanation:'Gain practical experience is a common academic/work collocation.'},
 {q:'The author makes a ___ argument for renewable energy.',options:['convincing','convinced','convince','convincingly'],a:0,focus:'convincing argument',explanation:'Convincing is the adjective describing the argument.'},
 {q:'The scheme is designed to ___ inequalities between regions.',options:['address','discuss about','speak','approach to'],a:0,focus:'address inequalities',explanation:'Address a problem/inequality means take action to deal with it.'},
 {q:'The evidence does not ___ the claim made in the introduction.',options:['support','assist to','help for','hold with'],a:0,focus:'support a claim',explanation:'Support a claim is precise academic language.'},
 {q:'The policy may have unintended ___ for low-income families.',options:['consequences','results to','effects on of','outcomes for to'],a:0,focus:'unintended consequences for',explanation:'Consequences for someone/something is the natural pattern.'},
 {q:'The survey was conducted on a ___ scale.',options:['large','largely','largeness','enlarge'],a:0,focus:'on a large scale',explanation:'Large is the adjective in the fixed phrase “on a large scale”.'},
 {q:'The findings ___ light on the causes of urban migration.',options:['shed','shine to','give up','putted'],a:0,focus:'shed light on',explanation:'Shed light on means make something clearer.'},
 {q:'A clear timetable helps learners ___ their time effectively.',options:['manage','control over','govern to','handle with'],a:0,focus:'manage time',explanation:'Manage time is the natural collocation.'}
];
const P40_GRAMMAR=[
 {q:'Choose the grammatically correct sentence.',options:['The number of applicants have increased.','The number of applicants has increased.','A number of applicant has increased.','The number applicants have increased.'],a:1,focus:'subject–verb agreement',explanation:'The head noun is “number” (singular), so use “has”.'},
 {q:'Choose the correct form: “Despite ___ limited resources, the team completed the study.”',options:['have','having','to have','had'],a:1,focus:'despite + noun / gerund',explanation:'Despite is a preposition, so it is followed by a noun phrase or gerund.'},
 {q:'Choose the best completion: “The results would be more reliable if the sample ___ larger.”',options:['is','was','were','will be'],a:2,focus:'second conditional / irrealis were',explanation:'A hypothetical condition commonly uses “if … were” in formal English.'},
 {q:'Choose the correct relative clause.',options:['The scheme, which was introduced in 2020, has expanded.','The scheme, that was introduced in 2020, has expanded.','The scheme, who was introduced in 2020, has expanded.','The scheme, where was introduced in 2020, has expanded.'],a:0,focus:'non-defining relative clause',explanation:'Use “which” in a non-defining clause; “that” is not used after a comma in this construction.'},
 {q:'Choose the correct passive form: “The data ___ by two independent researchers.”',options:['analysed','were analysed','was analysing','has analyse'],a:1,focus:'past simple passive + plural subject',explanation:'The plural noun “data” takes “were” in this sentence; the passive is be + past participle.'},
 {q:'Choose the correct article: “It is ___ useful approach to the problem.”',options:['a','an','the','no article'],a:0,focus:'indefinite article by sound',explanation:'Useful begins with a /juː/ consonant sound, so use “a”.'},
 {q:'Choose the best completion: “By the time the survey ended, 800 responses ___.”',options:['collect','were collecting','had been collected','have collected'],a:2,focus:'past perfect passive',explanation:'The collection was completed before another past time; use had been + past participle.'},
 {q:'Choose the correct parallel structure.',options:['The policy aims to reduce costs, improving access and that quality rises.','The policy aims to reduce costs, improve access and raise quality.','The policy aims reducing costs, to improve access and raising quality.','The policy aims to reduce costs, access improvement and raise quality.'],a:1,focus:'parallel infinitive structure',explanation:'Three coordinated verbs follow “aims to”: reduce, improve and raise.'},
 {q:'Choose the correct form: “Neither the lecturer nor the students ___ satisfied.”',options:['was','is','were','has been'],a:2,focus:'notional agreement with nearest subject',explanation:'With neither…nor, the verb often agrees with the nearest subject; “students” is plural.'},
 {q:'Choose the correct comparative structure.',options:['The more carefully data are collected, the more reliable the results become.','More carefully data are collected, more reliable results become.','The most carefully data are collected, the more reliable results become.','The more careful data collected, the more reliable results become.'],a:0,focus:'the comparative…, the comparative…',explanation:'Use “the + comparative” in both clauses.'},
 {q:'Choose the correct verb pattern: “The findings suggest that further research ___ necessary.”',options:['is','be','to be','being'],a:0,focus:'suggest that + finite clause',explanation:'Here suggest is followed by a that-clause with the finite verb “is”.'},
 {q:'Choose the correct use of an uncountable noun.',options:['many informations','a piece of advice','several researches','an equipment'],a:1,focus:'uncountable nouns',explanation:'Advice is uncountable; “a piece of advice” is correct.'},
 {q:'Choose the correct tense: “Since 2019, the city ___ its cycling network.”',options:['expanded','has expanded','is expanding yesterday','had expand'],a:1,focus:'present perfect with since',explanation:'Since + starting point usually requires present perfect for a situation continuing to now.'},
 {q:'Choose the correct inversion after a negative adverbial.',options:['Rarely the results have been questioned.','Rarely have the results been questioned.','Rarely did the results questioned.','Rarely the results were questioned have.'],a:1,focus:'negative adverbial inversion',explanation:'Fronted “rarely” triggers auxiliary-subject inversion.'},
 {q:'Choose the most accurate form: “The report is worth ___ in detail.”',options:['to read','reading','read','to reading'],a:1,focus:'worth + gerund',explanation:'Worth is followed by a noun or gerund.'},
 {q:'Choose the correct connector: “___ the sample was small, the pattern was consistent across both groups.”',options:['Despite','Although','Because of','In spite'],a:1,focus:'although + clause',explanation:'Although introduces a finite clause; despite and in spite of take noun phrases/gerunds.'},
 {q:'Choose the correct noun phrase.',options:['a highly effective policy','a high effective policy','an effectively policy','a policy highly effect'],a:0,focus:'adverb + adjective + noun',explanation:'An adverb modifies an adjective: highly effective policy.'},
 {q:'Choose the correct reported-speech form: “The researcher said that the results ___ preliminary.”',options:['are','were','will be now','be'],a:1,focus:'reported speech backshift',explanation:'With a past reporting verb, backshift to “were” is the conventional answer.'},
 {q:'Choose the correct modal perfect: “The figures are inconsistent; an error ___ occurred.”',options:['must have','must to have','should be','can have to'],a:0,focus:'modal + have + past participle',explanation:'Must have occurred expresses a strong deduction about the past.'},
 {q:'Choose the correct form: “The policy prevented residents ___ the river.”',options:['to access','from accessing','access','for access'],a:1,focus:'prevent + object + from + gerund',explanation:'The standard pattern is prevent someone from doing something.'},
 {q:'Choose the correct clause: “The proposal was rejected, ___ surprised the committee.”',options:['that','what','which','who'],a:2,focus:'sentential relative clause',explanation:'Which can refer to the entire preceding clause.'},
 {q:'Choose the correct structure.',options:['Not only the plan reduced costs, but it also improved access.','Not only did the plan reduce costs, but it also improved access.','Not only the plan did reduce costs, but also it improved access.','Not only did reduce the plan costs, but it improved access.'],a:1,focus:'not only inversion',explanation:'Fronted “not only” causes auxiliary-subject inversion.'},
 {q:'Choose the correct preposition: “This approach is similar ___ the one used in earlier studies.”',options:['with','to','for','by'],a:1,focus:'similar to',explanation:'The adjective similar takes the preposition to.'},
 {q:'Choose the correct completion: “The fewer resources a school has, the ___ it may be to provide specialist support.”',options:['difficult','more difficult','most difficult','difficulty'],a:1,focus:'the comparative, the comparative',explanation:'Use “the fewer…, the more difficult…”.'}
];
const P40_PRONUNCIATION=[
 ['The evidence suggests a gradual but significant change in public attitudes.','Contrast stress · EVIDENCE / GRADUAL / SIGNIFICANT','Group the sentence into evidence → trend → impact.'],
 ['Although the initial cost is high, the long-term benefits may outweigh it.','Concession · ALTHOUGH / LONG-TERM / OUTWEIGH','Mark a slight pause after the subordinate clause.'],
 ['A reliable transport network can reduce congestion and improve access to employment.','Word stress · RELIABLE / TRANSPORT / CONGESTION / EMPLOYMENT','Keep content words prominent; reduce articles and prepositions.'],
 ['One possible explanation is that people respond differently to financial incentives.','Thought groups · ONE POSSIBLE EXPLANATION / IS THAT…','Do not pause between “is” and its that-clause.'],
 ['The extent to which technology improves learning depends on how it is used.','Chunking · THE EXTENT TO WHICH / DEPENDS ON','Keep the opening noun phrase together.'],
 ['It would be misleading to assume that every increase represents genuine progress.','Sentence stress · MISLEADING / EVERY / GENUINE PROGRESS','Stress the qualification rather than every function word.'],
 ['From an economic perspective, prevention is often more effective than treatment.','Contrast · PREVENTION / MORE EFFECTIVE / TREATMENT','Use a clear contrastive fall on “treatment”.'],
 ['The findings are consistent with earlier research, but they do not prove causation.','Correction cue · CONSISTENT / BUT / NOT PROVE','Make the contrast after “but” audible.'],
 ['A balanced approach should consider both immediate needs and future consequences.','Pausing · IMMEDIATE NEEDS / FUTURE CONSEQUENCES','Use a short pause between the two parallel noun phrases.'],
 ['If governments invest in prevention, they may reduce pressure on public services.','Conditional chunk · IF… / THEY MAY…','Avoid separating “if” from its complete clause.'],
 ['The main drawback is not the technology itself, but the way it is implemented.','Contrastive stress · NOT / BUT / IMPLEMENTED','Make the correction contrast obvious.'],
 ['In the long run, educational equality depends on sustained and targeted investment.','Stress · LONG RUN / EQUALITY / SUSTAINED / TARGETED','Do not give equal stress to every word.']
];

const p40OldQuestion=p37Question;
p37Question=function(id){const m=p37ModuleState(id),ix=(day()*3+(m.round||0)*7-1);if(id==='collocations')return P40_COLLOCATIONS[((ix%P40_COLLOCATIONS.length)+P40_COLLOCATIONS.length)%P40_COLLOCATIONS.length];if(id==='grammar')return P40_GRAMMAR[((ix%P40_GRAMMAR.length)+P40_GRAMMAR.length)%P40_GRAMMAR.length];return p40OldQuestion(id);};

function p40PronKind(){return 'p40-pronunciation-r'+p37ModuleState('pronunciation').round;}
function p40PronKey(){return `${day()}:${p37ModuleState('pronunciation').round}`;}
function p40PronunciationMission(draft,round){const t=P40_PRONUNCIATION[(day()*5+round*3-1)%P40_PRONUNCIATION.length];return `<div class="p40-pron-grid"><section class="p37-panel"><div class="eyebrow">STAGE 40 · PRONUNCIATION INTELLIGENCE · ROUND ${round+1}</div><h3>Listen → mark stress → record → replay</h3><blockquote class="p40-pron-phrase">${esc(t[0])}</blockquote><p class="p40-pron-target"><b>Focus:</b> ${esc(t[1])}</p><p class="p37-note">${esc(t[2])}</p><div class="p37-row"><button class="btn primary" data-p36-say="${esc(t[0])}">🔊 Play model voice</button><button class="btn outline" data-p40-tts-slow="0.78">Slow model</button><button class="btn outline" data-p40-tts-slow="1">Normal model</button></div><p class="p37-note">Model is browser text-to-speech, not a native-speaker reference recording. Compare intelligibility, rhythm and word stress—not accent imitation.</p></section><section class="p37-panel"><div class="eyebrow">YOUR RECORDING · SAVED ON THIS DEVICE</div><div class="p37-row"><button class="btn primary" data-p40-pron-start>● Start recording</button><button class="btn outline" data-p40-pron-stop disabled>Stop & save</button><span id="p40PronStatus" class="p37-status" aria-live="polite">No recording in this round yet.</span></div><audio id="p40PronunciationPlayback" controls preload="none" style="width:100%;margin-top:12px"></audio><div class="p40-pron-checks">${[['stress','Primary stress is on the intended content word'],['sentence','Sentence stress highlights contrast or new information'],['chunk','Thought groups preserve meaning'],['intonation','Intonation supports the communicative purpose'],['final','Word endings / final consonants are intelligible'],['clarity','The replay is understandable without reading the transcript']].map(([k,l])=>`<label class="p37-check"><input type="checkbox" data-p37-check="${k}" ${draft.checks?.[k]?'checked':''}> ${l}</label>`).join('')}</div><label class="p37-field">Timestamp + exact audio observation<textarea data-p37-field="reason" rows="3" placeholder="00:14 — stress moved to the wrong word; replay and compare…">${esc(draft.reason||'')}</textarea></label><p class="p37-note">A saved recording is required before this pronunciation round can be scored. The app does not claim automated phoneme grading.</p></section></div>`;}

// Replace weak single-phrase pronunciation mission with a dedicated recorder that never overwrites Speaking Part audio.
const p40OldMission=p37Mission;
p37Mission=function(id){let h=p40OldMission(id);const d=p37Draft(id),m=p37ModuleState(id);if(id==='pronunciation'){const mark=h.indexOf('<div class="p37-columns">');const end=h.indexOf('<details class="p37-guide">',mark);if(mark>=0&&end>mark){h=h.slice(0,mark)+p40PronunciationMission(d,m.round)+h.slice(end);}else{console.warn('Stage 40: pronunciation mission replacement anchor not found');}}
 if(id==='paraphrase'){
   h=h.replace(/<label class="p37-check"><input type="checkbox" data-p37-check="meaning"[^>]*> I checked that the rewritten claim keeps the same scope and certainty\.<\/label>/,
   `<div class="p40-semantic-check"><b>Meaning-preservation gate</b>${[['meaning','Same central claim / proposition'],['scope','Same scope: who, what, when and how many'],['certainty','Same certainty: possible, likely, proven or required'],['time','Same time reference and comparison direction']].map(([k,l])=>`<label class="p37-check"><input type="checkbox" data-p37-check="${k}" ${d.checks?.[k]?'checked':''}> ${l}</label>`).join('')}</div>`);
 }
 if(id==='fluency'){
  const s=state.speaking[day()]||{};
  const bar=`<section class="p40-fluency-rec"><div class="eyebrow">SPOKEN TRANSFER · PART 3-STYLE RESPONSE</div><h3>Speak your four-part answer aloud</h3><p class="p37-note">The four planning boxes are not enough by themselves. Use this live transcript to capture the complete 45–90 second response.</p><div class="p37-row"><button class="btn primary small" data-p37-asr-start="challengeResponse">🎙 Start spoken response transcript</button><button class="btn outline small" data-p37-asr-stop>Stop</button><span data-p40-asr-status="challengeResponse" class="p37-status">Ready</span></div><label class="p37-field">Full spoken response<textarea class="textarea" data-speak-field="challengeResponse" rows="5" placeholder="Speak in English. Recognised final words appear here…">${esc(s.challengeResponse||'')}</textarea></label><label class="p40-asr-language">Recognition language <select class="select" data-p40-asr-lang="challengeResponse"><option value="en-GB">English (UK)</option><option value="en-US">English (US)</option></select></label></section>`;
  h=h.replace('<div class="p37-note">Then connect the four parts in one uninterrupted spoken answer; do not read each box aloud mechanically.</div>',`<div class="p37-note">Then connect the four parts in one uninterrupted spoken answer; do not read each box aloud mechanically.</div>${bar}`);
 }
 if(id==='collocations'){
  const q=p37Question('collocations');h=h.replace('<h3>'+esc(q.q)+'</h3>',`<h3>${esc(q.q)}</h3><div class="p40-target"><b>Collocation target:</b> ${esc(q.focus||'Natural academic phrase')}<br><span>${esc(q.explanation||'')}</span></div>`);
 }
 if(id==='grammar'){
  const q=p37Question('grammar');h=h.replace('<h3>'+esc(q.q)+'</h3>',`<h3>${esc(q.q)}</h3><div class="p40-target"><b>Rule focus:</b> ${esc(q.focus||'Grammar accuracy')}</div>`);
 }
 if(id==='vocabulary'){
  const w=WORDS.find(x=>x.id===Number(d.wordId));if(w){const tools=`<div class="p40-word-tools"><button class="btn small outline" data-p36-say="${esc(w.word)}">🔊 Listen</button><a target="_blank" rel="noopener" href="${vxCambridgeUrl(w.word)}">Cambridge meaning ↗</a><button class="btn small outline" data-p37-lookup="${w.id}">Fetch full dictionary entry</button></div><p class="p37-note">IPA is printed from the indexed pronunciation field where available. Translation/definition lookups are provisional until the learner verifies the intended sense.</p>`;h=h.replace('</h2><p class="p37-ipa">',`</h2>${tools}<p class="p37-ipa">`);}}
 return h;};

// Stronger semantic gate and real audio evidence for the two language labs.
const p40OldEvaluate=p37Evaluate;
p37Evaluate=function(id){const d=p37Draft(id);if(id==='paraphrase'){const needed=['meaning','scope','certainty','time'];if(!needed.every(k=>d.checks?.[k])){toast('Paraphrase gate: check claim, scope, certainty and time separately.');return;}}
 if(id==='pronunciation'){const key=p40PronKey(),saved=state.stage40?.pronunciation?.[key]?.saved;if(!saved){toast('First make and save a pronunciation recording in this round.');return;}}
 if(id==='fluency'){const txt=String(state.speaking?.[day()]?.challengeResponse||'');if(p36Words(txt).length<25){toast('Complete the spoken-response transcript (at least 25 words) before scoring this fluency round.');return;}}
 return p40OldEvaluate(id);};

// Add official-explanation feedback to original formative scoring without changing saved histories.
const p40OldScore=p37ScoreAndSave;
p37ScoreAndSave=function(id,score,feedback,next,meta={}){if(id==='grammar'||id==='collocations'){const q=p37Question(id);feedback+=` Learning note: ${q?.explanation||'Review the rule and use it in a new context.'}`;meta={...meta,question:q?.q,focus:q?.focus,answerKey:q?.options?.[q?.a]};}return p40OldScore(id,score,feedback,next,meta);};

// Field-level language, ASR status and timestamps are stored alongside the relevant transcript.
const p40OldSetASR=p37SetASRStatus;
p37SetASRStatus=function(msg,kind='info',target=p37RecognitionTarget){try{p40OldSetASR(msg,kind,target);}catch(_){}document.querySelectorAll(`[data-p40-asr-status="${target}"]`).forEach(el=>{el.textContent=msg;el.className='p37-status '+kind;});};
document.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-p40-asr-lang]')){window.__IELTS_BOOST_SPEECH_LANG__=t.value||'en-GB';p37SetASRStatus('Recognition language: '+window.__IELTS_BOOST_SPEECH_LANG__,'info',t.dataset.p40AsrLang);}},true);
const p40OldStartASR=p37StartASR;p37StartASR=function(target){const s=state.speaking[day()]||(state.speaking[day()]={});s.asrMeta=s.asrMeta||{};s.asrMeta[target]=s.asrMeta[target]||{confidences:[]};s.asrMeta[target].startedAt=new Date().toISOString();s.asrMeta[target].startedLanguage=window.__IELTS_BOOST_SPEECH_LANG__||'en-GB';const ok=p40OldStartASR(target);s.asrMeta[target].startRequested=!!ok;save();return ok;};
const p40OldStopASR=p37StopASR;p37StopASR=function(){const target=p37RecognitionTarget,s=state.speaking[day()]||(state.speaking[day()]={});s.asrMeta=s.asrMeta||{};s.asrMeta[target]=s.asrMeta[target]||{};s.asrMeta[target].stoppedAt=new Date().toISOString();const r=p40OldStopASR();save();return r;};

// Independent pronunciation recorder. It writes to its own IndexedDB key and never touches Part 1/2/3.
let p40PronRecorder=null,p40PronStream=null,p40PronChunks=[];
function p40SetPronStatus(msg,kind='info'){const el=$('#p40PronStatus');if(el){el.textContent=msg;el.className='p37-status '+kind;}}
async function p40StartPronRecorder(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){p40SetPronStatus('MediaRecorder/getUserMedia is not available here. Use the main Speaking recorder instead.','warn');toast('Audio recording API unavailable in this browser context.');return;}
 try{p40PronStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});let type='';for(const t of ['audio/webm;codecs=opus','audio/webm','audio/mp4']){try{if(MediaRecorder.isTypeSupported?.(t)){type=t;break;}}catch(_){}}
  p40PronChunks=[];p40PronRecorder=type?new MediaRecorder(p40PronStream,{mimeType:type}):new MediaRecorder(p40PronStream);p40PronRecorder.ondataavailable=e=>{if(e.data&&e.data.size)p40PronChunks.push(e.data);};p40PronRecorder.onerror=()=>p40SetPronStatus('Recorder error. Check microphone permissions and available storage.','warn');p40PronRecorder.onstop=async()=>{try{const blob=new Blob(p40PronChunks,{type:p40PronRecorder?.mimeType||'audio/webm'});if(!blob.size)throw new Error('Recording is empty');const kind=p40PronKind(),name=`IELTS-Boost-Day-${day()}-Pronunciation-Round-${p37ModuleState('pronunciation').round+1}.${blob.type.includes('mp4')?'m4a':'webm'}`;await storeBlob(kind,day(),blob,name);state.stage40=state.stage40||{};state.stage40.pronunciation=state.stage40.pronunciation||{};state.stage40.pronunciation[p40PronKey()]={saved:true,name,size:blob.size,type:blob.type,at:new Date().toISOString()};save();const player=$('#p40PronunciationPlayback');if(player){if(player.dataset.objectUrl)URL.revokeObjectURL(player.dataset.objectUrl);const u=URL.createObjectURL(blob);player.src=u;player.dataset.objectUrl=u;}p40SetPronStatus(`Saved · ${(blob.size/1024).toFixed(0)} KB · replay before marking the checklist`,'good');toast('Pronunciation audio saved to this device.');}catch(err){p40SetPronStatus(`Could not save audio: ${err.message}`,'warn');toast('Audio save failed: '+err.message);}finally{for(const tr of p40PronStream?.getTracks?.()||[])tr.stop();p40PronStream=null;p40PronRecorder=null;p40PronChunks=[];const b=$('[data-p40-pron-start]'),stop=$('[data-p40-pron-stop]');if(b)b.disabled=false;if(stop)stop.disabled=true;}};
  p40PronRecorder.start(250);const b=$('[data-p40-pron-start]'),stop=$('[data-p40-pron-stop]');if(b)b.disabled=true;if(stop)stop.disabled=false;p40SetPronStatus('Recording… speak the full phrase, then Stop & save.','good');
 }catch(err){for(const tr of p40PronStream?.getTracks?.()||[])tr.stop();p40PronStream=null;p40SetPronStatus(`Microphone could not start: ${err.name||''} ${err.message||err}`,'warn');toast('Allow microphone access in Chrome Site settings.');}}
document.addEventListener('click',e=>{const t=e.target.closest('[data-p40-pron-start],[data-p40-pron-stop]');if(!t)return;if(t.hasAttribute('data-p40-pron-start')){p40StartPronRecorder();return;}if(t.hasAttribute('data-p40-pron-stop')){if(p40PronRecorder&&p40PronRecorder.state!=='inactive')p40PronRecorder.stop();return;}},true);
document.addEventListener('click',e=>{const t=e.target.closest('[data-p40-tts-slow]');if(!t)return;const block=t.closest('.p40-pron-grid')?.querySelector('blockquote');if(!block||!('speechSynthesis'in window))return;speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(block.textContent);u.lang='en-GB';u.rate=Number(t.dataset.p40TtsSlow)||0.85;speechSynthesis.speak(u);},true);

// A visible, resumable vocabulary enrichment queue. Counts are computed from actual cached/bundled fields.
function p40WordCache(w){return{...(p36Ensure().vocabularyCache[w.word]||{}),...(p37Ensure().vocabulary.cache[w.word]||{}),...(state.vocabCache?.[w.word]||{})};}
function p40VocabCoverage(){const trans=WORDS.slice(0,4000).filter(w=>w.uzbek||p40WordCache(w).uzbek).length;const defs=WORDS.slice(0,9000).filter(w=>w.meaning_en||p40WordCache(w).meaning_en).length;const ipa=WORDS.slice(0,9000).filter(w=>w.ipa_us||w.ipa_uk||p40WordCache(w).ipa_api).length;const full=WORDS.filter(w=>{const c=p40WordCache(w);return(w.meaning_en||c.meaning_en)&&(w.uzbek||c.uzbek)&&(w.example||c.example)&&(w.part_of_speech||c.part_of_speech);}).length;return{trans,defs,ipa,full};}
