/* ---- STAGE 45 extension starts ---- */
/* Evidence-led laboratories: distinguish objective answer-key evidence from task completion/self-review. */
const P45_VERSION=LAB_QUALITY_ENGINE_VERSION;
function p45Ensure(){const g=p37G();g.stage45=g.stage45||{attempts:[],transfers:{},migrations:{}};g.stage45.attempts=Array.isArray(g.stage45.attempts)?g.stage45.attempts:[];g.stage45.transfers=g.stage45.transfers||{};g.stage45.migrations=g.stage45.migrations||{};return g.stage45;}
function p45Key(id,round=0,baseDay=day()){return `${baseDay}:${id}:${round}`;}
function p45DayForTransfer(){return day()<84?day()+1:day();}
function p45WordCount(x){return (String(x||'').match(/[A-Za-z]+(?:['’-][A-Za-z]+)*/g)||[]).length;}
function p45Normal(x){return String(x||'').toLowerCase().normalize('NFKD').replace(/[’‘`]/g,"'").replace(/[^a-z0-9' ]/g,' ').replace(/\s+/g,' ').trim();}
function p45QuestionFor(id,targetDay,round){
 const d=CORE[Math.max(0,Math.min(83,targetDay-1))]||CORE[0];
 if(id==='reading'){const a=d.reading?.questions||[];return a.length?a[(targetDay+round+1)%a.length]:null;}
 if(id==='listening'){const a=d.listening?.questions||[];return a.length?a[(targetDay+round+2)%a.length]:null;}
 if(id==='collocations')return P36_COLLOCATIONS[(targetDay+round+1)%P36_COLLOCATIONS.length]||P36_COLLOCATIONS[0];
 if(id==='grammar')return P36_GRAMMAR[(targetDay+round+2)%P36_GRAMMAR.length]||P36_GRAMMAR[0];
 return null;
}
function p45TransferSpec(id,round){
 const targetDay=p45DayForTransfer(),d=CORE[targetDay-1]||CORE[0],q=p45QuestionFor(id,targetDay,round);
 const base={id,round,targetDay,isPostCourse:day()===84,label:day()===84?'Post-course cumulative transfer':`Day ${targetDay} transfer`};
 if(id==='reading'){const correctLabel=q?.options?.[Number(q?.answer)]||'';const notGiven=String(q?.type||'').toLowerCase().includes('not given')&&/not given/i.test(correctLabel);return {...base,kind:'objective',question:q,source:d.reading.passage,title:d.reading.title,notGiven,prompt:'Yangi matndan savolga mos dalil top. Javobni tanla, aniq iborani keltir va scope/paraphrase sababini tushuntir.'};}
 if(id==='listening')return {...base,kind:'objective',question:q,source:d.listening.script,title:d.listening.title,audio:`./audio/listening-day-${String(targetDay).padStart(2,'0')}.mp3`,prompt:'Yangi audio’ni transcriptni ochmasdan oxirigacha tingla. Javobni tanla va eshitilgan dalilni yoz.'};
 if(id==='writing')return {...base,kind:'process',prompt:d.writing.task2_prompt,title:'New Academic Task 2 prompt',instructions:'Kamida 35 so‘zda position, ikki asosiy sabab va bitta konkret misol uchun mini-plan yoz. To‘liq essay emas; bu transfer checkpoint.',evidencePrompt:'Savolning qaysi ikki talabi rejangda javob topganini ko‘rsat.'};
 if(id==='speaking')return {...base,kind:'process',prompt:d.speaking.part3[(targetDay+round)%d.speaking.part3.length],title:'New Speaking Part 3 prompt',instructions:'Savolga kamida 35 so‘zli tabiiy javob yoz yoki oldin ovoz yozib transcriptni kiriting. So‘ng bitta kuchli va bitta yaxshilanishi kerak bo‘lgan jihatni qayd et.',evidencePrompt:'Javobingdan aniq ibora yoki audio timestamp bilan self-review yoz.'};
 if(id==='collocations')return {...base,kind:'objective',question:q,title:'New collocation in context',prompt:'To‘g‘ri collocation’ni tanla, so‘ng uni boshqa mavzuda tabiiy gapda ishlat.'};
 if(id==='pronunciation'){
  const set=VX_SETS[targetDay-1]||[],w=set.find(x=>x&&x.word&&x.ipa_uk)||set.find(x=>x&&x.word)||null;
  const phrase=w?w.word:d.speaking.daily_chunk,ipa=w?.ipa_uk||'';
  return {...base,kind:'process',title:'New pronunciation target',phrase,ipa,instructions:'Modelni tingla, o‘zingni yozib qayta tingla. Stress, final sounds, thought groups va intelligibility bo‘yicha kamida uchta tekshiruv qil. Ilova fonetik talaffuzni avtomatik baholamaydi.'};
 }
 if(id==='paraphrase'){
  const sentences=d.reading.passage.split(/(?<=[.!?])\s+/).map(x=>x.trim()).filter(x=>p45WordCount(x)>=12);
  const sentence=sentences[(round+2)%Math.max(1,sentences.length)]||sentences[0]||d.reading.passage.slice(0,280);
  return {...base,kind:'process',title:'New meaning-preservation task',sourceSentence:sentence,instructions:'Mazmunni saqlab, kamida 15 so‘z bilan qayta yoz. Subject, scope va certainty o‘zgarmasin.'};
 }
 if(id==='grammar')return {...base,kind:'objective',question:q,title:'New grammar transfer',prompt:'Javob variantini tanla, qoidani o‘z so‘zing bilan ayt va boshqa mavzuda yangi misol gap tuz.'};
 if(id==='vocabulary'){
  const set=VX_SETS[targetDay-1]||[],w=set.find(x=>x&&x.meaning_en&&x.uzbek&&x.example)||set.find(x=>x&&x.meaning_en&&x.uzbek)||null;
  return {...base,kind:'process',title:'New active-recall word',word:w,instructions:'Ma’noni reveal qilmasdan xotiradan yoz. Inglizcha definition, o‘zbekcha ma’no va yangi kontekstdagi gap bilan mustahkamla. O‘xshash so‘zlar avtomatik to‘g‘ri ma’no deb qabul qilinmaydi.'};
 }
 if(id==='fluency')return {...base,kind:'process',title:'New academic fluency prompt',prompt:d.speaking.part3[(targetDay+round+1)%d.speaking.part3.length],instructions:'Claim → reason → example → qualification qismlarini to‘ldir. Keyin ularni bitta tabiiy javobga ulang.'};
 return {...base,kind:'process',title:LAB_LABELS[id]||id};
}
function p45TransferState(key){const s=p45Ensure();s.transfers[key]=s.transfers[key]||{fields:{},checks:{},answer:'',audioCompleted:false,submitted:false};const t=s.transfers[key];t.fields=t.fields||{};t.checks=t.checks||{};return t;}
function p45Input(label,field,value='',rows=3,placeholder=''){return `<label class="p37-field">${esc(label)}<textarea class="textarea" data-p45-field="${field}" rows="${rows}" placeholder="${esc(placeholder)}">${esc(value||'')}</textarea></label>`;}
function p45ErrorFields(t){return `<div class="p45-error-grid"><label class="p37-field">Agar javob noto‘g‘ri bo‘lsa — xato sababini tanla<select class="select" data-p45-field="errorCause"><option value="">Sababni tanla…</option>${Object.entries(ERROR_CAUSES).map(([k,v])=>`<option value="${k}" ${t.fields.errorCause===k?'selected':''}>${esc(v)}</option>`).join('')}</select></label>${p45Input('Keyingi urinishda xatoni qanday oldini olasan?','repairPlan',t.fields.repairPlan||'',2,'Aniq strategiya: ...')}</div>`;}
function p45ObjectiveOptions(q,t){const opts=q?.options||q?.o||[];return opts.map((v,i)=>`<label class="p37-option"><input type="radio" name="p45-answer" data-p45-answer value="${i}" ${String(t.answer)===String(i)?'checked':''}><span>${esc(v)}</span></label>`).join('');}
function p45TransferMarkup(id){
 const m=p37ModuleState(id),round=m.round||0,done=(m.doneByDay?.[day()]||[]).includes(round),spec=p45TransferSpec(id,round),key=p45Key(id,round),t=p45TransferState(key),q=spec.question;
 let body='';
 if(!done)return `<section class="p45-transfer p45-locked"><div class="p45-head"><span class="eyebrow">STAGE 45 · TRANSFER CHALLENGE</span><b>Finish this lab round to unlock the fresh transfer task.</b></div><p class="p37-note">Transfer is optional additional practice. It does not block the 84-day plan or the next lab.</p></section>`;
 if(t.submitted){const result=t.correct===true?'Answer-key transfer: correct.':t.correct===false?'Answer-key transfer: incorrect — error diagnosis saved.':'Process evidence submitted; no automatic language-accuracy claim.';return `<section class="p45-transfer"><div class="p45-head"><span class="eyebrow">STAGE 45 · ${esc(spec.label.toUpperCase())}</span><b>✓ Transfer recorded</b></div><p>${esc(result)}</p><p class="p37-note">${esc(t.feedback||'Saved locally.')} ${t.correct===false?`Suggested explanation: ${esc(q?.explanation||q?.e||'Review the rule and retry on a fresh item.')}`:''}</p><button type="button" class="btn outline small" data-p45-transfer-reset="${id}" data-p45-round="${round}">Try this transfer again</button></section>`;}
 if(id==='reading')body=`<div class="p45-source"><b>${esc(spec.title)}</b><p>${esc(spec.source.slice(0,1800))}${spec.source.length>1800?'…':''}</p></div><h4>${esc(q?.question||'Choose the best answer.')}</h4>${p45ObjectiveOptions(q,t)}${p45Input(spec.notGiven?'Evidence (leave blank for a correct NOT GIVEN item)':'Exact evidence from the new passage','evidence',t.fields.evidence||'',3,spec.notGiven?'Do not invent a quote; leave blank or write “no exact quote”.':'Copy a phrase/sentence from the new passage…')}${p45Input(spec.notGiven?'Why is the information absent from the passage?':'Why does this evidence answer the exact question?','reason',t.fields.reason||'',3,spec.notGiven?'Explain specifically that the passage does not state the claim…':'Explain the paraphrase, scope or contrast…')}`;
 else if(id==='listening')body=`<div class="p45-source"><b>${esc(spec.title)}</b><p>Original IELTS Boost scripted practice audio; not an official IELTS recording.</p><audio id="p45TransferAudio" controls preload="metadata" src="${spec.audio}"></audio><span class="p37-status">${t.audioCompleted?'Audio completed':'Listen to the full audio before submitting.'}</span></div><h4>${esc(q?.question||'Choose the final confirmed detail.')}</h4>${p45ObjectiveOptions(q,t)}${p45Input('Exact words / signal heard','evidence',t.fields.evidence||'',3,'Write the phrase or final confirmed detail…')}${p45Input('Which distractor could mislead you and why?','reason',t.fields.reason||'',2,'Explain the correction or contrast…')}`;
 else if(id==='writing')body=`<div class="p45-source"><b>${esc(spec.title)}</b><p>${esc(spec.prompt)}</p><p class="p37-note">${esc(spec.instructions)}</p></div>${p45Input('Thesis + two developed idea directions + one example','text',t.fields.text||'',5,'Write a focused 35+ word plan…')}${p45Input(spec.evidencePrompt,'evidence',t.fields.evidence||'',2,'Identify the requirements you addressed…')}`;
 else if(id==='speaking')body=`<div class="p45-source"><b>${esc(spec.title)}</b><p>${esc(spec.prompt)}</p><p class="p37-note">${esc(spec.instructions)}</p></div>${p45Input('Your spoken response / transcript (35+ words)','text',t.fields.text||'',6,'Speak first, then enter or dictate your transcript…')}${p45Input(spec.evidencePrompt,'evidence',t.fields.evidence||'',2,'Quote a phrase or give an audio timestamp…')}`;
 else if(id==='collocations')body=`<div class="p45-source"><b>${esc(spec.title)}</b></div><h4>${esc(q?.q||'Choose the natural collocation.')}</h4>${p45ObjectiveOptions(q,t)}${p45Input('Write a new 10+ word sentence using the target collocation','text',t.fields.text||'',3,'Use a different topic or context…')}${p45Input('Explain the grammar pattern / register','reason',t.fields.reason||'',2,'Adjective + noun, verb pattern, register…')}`;
 else if(id==='pronunciation')body=`<div class="p45-source"><b>${esc(spec.title)}</b><p class="p45-pron-target">${esc(spec.phrase)}</p>${spec.ipa?`<p>UK IPA: ${esc(spec.ipa)}</p>`:''}<p class="p37-note">${esc(spec.instructions)}</p></div><div class="p37-row"><button type="button" class="btn outline" data-p36-say="${esc(spec.phrase)}">🔊 Play target</button><button type="button" class="btn outline" data-p45-open-speaking>Open Speaking recorder</button></div>${[['stress','Word stress'],['final','Final consonants / endings'],['chunk','Thought groups / linking'],['intonation','Intonation'],['clarity','Intelligibility'],['replay','Second recording replayed']].map(([k,l])=>`<label class="p37-check"><input type="checkbox" data-p45-check="${k}" ${t.checks[k]?'checked':''}> ${l}</label>`).join('')}${p45Input('Timestamp + precise sound target','evidence',t.fields.evidence||'',2,'00:12 — word stress on ...')}`;
 else if(id==='paraphrase')body=`<div class="p45-source"><b>${esc(spec.title)}</b><blockquote>${esc(spec.sourceSentence)}</blockquote><p class="p37-note">${esc(spec.instructions)}</p></div>${p45Input('Your meaning-preserving paraphrase (15+ words)','text',t.fields.text||'',5,'Keep the original proposition and scope…')}<div class="p45-checks">${[['meaning','Same core claim'],['scope','Same subject and scope'],['certainty','Same certainty / qualification']].map(([k,l])=>`<label class="p37-check"><input type="checkbox" data-p45-check="${k}" ${t.checks[k]?'checked':''}> ${l}</label>`).join('')}</div>${p45Input('Explain two changes without changing meaning','evidence',t.fields.evidence||'',2,'Syntax shift, word class, precise synonym…')}`;
 else if(id==='grammar')body=`<div class="p45-source"><b>${esc(spec.title)}</b></div><h4>${esc(q?.q||'Choose the grammatically correct answer.')}</h4>${p45ObjectiveOptions(q,t)}${p45Input('Explain the rule in your own words','reason',t.fields.reason||'',2,'Name the grammatical rule…')}${p45Input('Write a new example using the same structure (8+ words)','text',t.fields.text||'',2,'Use a different subject/topic…')}`;
 else if(id==='vocabulary')body=`<div class="p45-source"><b>${esc(spec.title)}</b><p class="p45-pron-target">${esc(spec.word?.word||'Vocabulary target')}</p>${spec.word?.ipa_uk?`<p>UK IPA: ${esc(spec.word.ipa_uk)}</p>`:''}<p class="p37-note">${esc(spec.instructions)}</p></div><div class="p37-row"><button class="btn outline" type="button" data-p36-say="${esc(spec.word?.word||'')}">🔊 Hear word</button></div>${p45Input('Recall the English definition + Uzbek meaning','text',t.fields.text||'',3,'Write from memory before looking it up…')}${p45Input('Use the exact sense in a new context / collocation','evidence',t.fields.evidence||'',2,'Write an original sentence…')}`;
 else if(id==='fluency')body=`<div class="p45-source"><b>${esc(spec.title)}</b><p>${esc(spec.prompt)}</p><p class="p37-note">${esc(spec.instructions)}</p></div>${[['claim','Claim / position'],['reason','Reason / explanation'],['example','Specific example'],['qualification','Qualification / limitation']].map(([k,l])=>p45Input(l,k,t.fields[k]||'',2,`${l}…`)).join('')}`;
 const objective=spec.kind==='objective';
 return `<section class="p45-transfer"><div class="p45-head"><div><span class="eyebrow">STAGE 45 · ${esc(spec.label.toUpperCase())} · ROUND ${round+1}</span><h3>Fresh transfer challenge</h3><p>${esc(LAB_LABELS[id]||id)} · ${objective?'Answer-key checked where available':'Process / self-review evidence only'}</p></div><span class="p45-tag">OPTIONAL</span></div>${body}${objective?p45ErrorFields(t):''}<p class="p45-note">This is a new item from ${spec.isPostCourse?'the cumulative post-course review':'the next study day'}. It does not add minutes to your required daily plan.</p><div class="p37-row"><button type="button" class="btn primary" data-p45-transfer-submit="${id}" data-p45-round="${round}">Submit transfer evidence</button><span class="p37-status" id="p45TransferStatus">${objective?'New answer-key item':'No automatic language-quality grade'}</span></div><p class="p45-note">${objective?'A wrong answer requires an error cause and repair plan.':'A complete form records practice evidence, not verified mastery.'}</p></section>`;
}
function p45MissionPanel(id){const m=p37ModuleState(id),round=m.round||0,done=(m.doneByDay?.[day()]||[]).includes(round);return p45TransferMarkup(id);}
