const s47RenderSpeakingOriginal=renderSpeaking;
renderSpeaking=function(){let html=s47RenderSpeakingOriginal();const token=`${guidedSupport('speaking')}${resourceCardMarkup('speaking')}`;if(html.includes(token))html=html.replace(token,`${guidedSupport('speaking')}${s47SkillPackMarkup('speaking')}${resourceCardMarkup('speaking')}`);return html;};
const s47RenderListeningOriginal=renderListening;
renderListening=function(){let html=s47RenderListeningOriginal();const token=`${guidedSupport('listening')}${resourceCardMarkup('listening')}`;return html.replace(token,`${guidedSupport('listening')}${s47ResourceCard()}${s47SkillPackMarkup('listening')}${resourceCardMarkup('listening')}`);};
const s47RenderWritingOriginal=renderWriting;
renderWriting=function(){let html=s47RenderWritingOriginal();const plan=D().modules.writing,tab=state.writingTab||plan.primary_task&&plan.primary_task!=='both'&&plan.primary_task||'task2';if(tab==='task1'){const spec=R().resources?.writing?.task1||{},visual=renderTaskVisual(C().writing.task1_type||spec.type||'line_graph',day());if(html.includes(visual))html=html.replace(visual,visual+s47Task1Masterclass(spec));}const token=`${guidedSupport('writing')}${resourceCardMarkup('writing')}`;if(html.includes(token))html=html.replace(token,`${guidedSupport('writing')}${s47SkillPackMarkup('writing')}${resourceCardMarkup('writing')}`);return html;};

// Persistence for the Task 1 planner and the optional external resource self-check.
document.addEventListener('input',e=>{const t=e.target.closest?.('[data-s47-t1-field]');if(!t)return;state.stage47Task1=state.stage47Task1||{};const d=String(day());state.stage47Task1[d]=state.stage47Task1[d]||{overview:'',bodyOne:'',bodyTwo:'',accuracyNotes:'',planAudit:null};state.stage47Task1[d][t.dataset.s47T1Field]=t.value;save();});
document.addEventListener('change',e=>{const t=e.target.closest?.('[data-s47-listening-reviewed]');if(!t)return;state.stage47Listening=state.stage47Listening||{};state.stage47Listening[day()]={...(state.stage47Listening[day()]||{}),reviewed:!!t.checked,reviewedAt:t.checked?new Date().toISOString():null};save();});
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-s47-t1-action]');if(!b)return;const action=b.dataset.s47T1Action;state.stage47Task1=state.stage47Task1||{};const d=String(day()),st=state.stage47Task1[d]||{};const fields=['overview','bodyOne','bodyTwo','accuracyNotes'];if(action==='check-plan'){const spec=R().resources?.writing?.task1||{},required=spec.type==='process'?{overview:10,bodyOne:12,bodyTwo:12,accuracyNotes:6}:{overview:10,bodyOne:12,bodyTwo:12,accuracyNotes:6};const complete=fields.filter(k=>String(st[k]||'').trim().split(/\s+/).filter(Boolean).length>=required[k]);const missing=fields.filter(k=>!complete.includes(k));const message=missing.length?`${complete.length}/4 sections have enough planning text. Still develop: ${missing.join(', ')}. This is not a language-quality mark.`:'4/4 planning sections contain enough material. Now verify each statement against the visual; this is not an IELTS band or semantic grade.';state.stage47Task1[d]={...st,planAudit:{complete:complete.length,total:4,missing,message,at:new Date().toISOString()}};save();const out=$('#s47Task1PlanStatus');if(out)out.textContent=message;toast(missing.length?'Task 1 plan: more detail needed':'Task 1 plan structure check complete');}});
